'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const money=n=>(Number(n||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const num=s=>{if(typeof s==='number')return Number.isFinite(s)?s:NaN;let x=String(s??'').replace(/R\$|\s|\u00a0/g,'');if(!x)return 0;const neg=/^-/.test(x);x=x.replace(/^[-+]/,'');let v;if(/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(x))v=Number(x.replace(/\./g,'').replace(',','.'));else if(/^\d+,\d+$/.test(x))v=Number(x.replace(',','.'));else if(/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(x))v=Number(x.replace(/,/g,''));else if(/^\d+(\.\d+)?$/.test(x))v=Number(x);else v=NaN;return neg?-v:v};
