function catalog(){let data=DB.products.filter(p=>onlineOk(p)&&((category==='Todas')||p.category===category)&&(!search||plain(p.name+' '+p.description+' '+p.brand).includes(plain(search))));if(sort==='low')data.sort((a,b)=>a.price10-b.price10);if(sort==='high')data.sort((a,b)=>b.price10-a.price10);if(sort==='alpha')data.sort((a,b)=>a.name.localeCompare(b.name));return `<div class="page"><div class="page-title"><h1>🛒 Catálogo K10</h1><p>${data.length} produtos · Escolha o que vai gelar seu momento.</p></div><div class="toolbar"><span class="tiny muted">Categoria: ${esc(category)}</span><label class="field" style="width:205px">Ordenar por<select id="sort">${[['featured','Destaques'],['low','Menor preço'],['high','Maior preço'],['alpha','Nome A-Z']].map(([v,n])=>`<option ${sort===v?'selected':''} value="${v}">${n}</option>`).join('')}</select></label></div><div class="filter-pills">${['Todas',...categories.map(x=>x[0])].map(c=>`<button data-action="cat" class="${category===c?'active':''}" data-value="${esc(c)}">${esc(c)}</button>`).join('')}</div>${data.length?`<div class="products">${data.map(prodCard).join('')}</div>`:`<div class="empty-state"><strong>Nenhum produto encontrado</strong><p>Experimente outro nome ou categoria.</p>${button('Limpar busca','reset-catalog')}</div>`}</div>`}
function cartPage(){const lines=cartLines(),sub=cartTotal(),fee=mode==='entrega'&&sub<DB.settings.freeShipping?DB.settings.fee:0;return `<div class="page"><div class="page-title"><h1>🛒 Meu carrinho</h1><p>Revise as quantidades antes de fazer o pedido.</p></div>${!lines.length?`<div class="panel empty-state"><strong>Seu carrinho está vazio</strong><p>Adicione os produtos que você quer receber.</p>${button('Explorar catálogo','catalog','button',`data-go="catalog"`)}</div>`:`<div class="cart-layout"><div class="panel">${lines.map(l=>`<div class="line-item">${productPhoto(l.photo)}<div class="details"><strong>${esc(l.name)}</strong><small>${money(l.price)} por item</small><div class="quantity" style="margin-top:9px"><button data-action="qty" data-id="${esc(l.key)}" data-delta="-1" aria-label="Diminuir quantidade">−</button><b>${l.q}</b><button data-action="qty" data-id="${esc(l.key)}" data-delta="1" aria-label="Aumentar quantidade">+</button></div></div><strong>${money(l.price*l.q)}</strong></div>`).join('')}${button('Limpar carrinho','clear-cart','button dark','style="margin-top:15px"')}</div><aside class="panel"><h3>Resumo do pedido</h3><div class="summary"><span>Produtos</span><b>${money(sub)}</b></div><div class="summary"><span>Frete estimado</span><b>${mode==='retirada'?'Grátis':money(fee)}</b></div><div class="summary total"><span>Total estimado</span><b>${money(sub+fee)}</b></div>${button('Continuar para pagamento →','checkout','button block',`data-go="checkout"`)}</aside></div>`}</div>`}
function trackPage(){return `<div class="page"><div class="page-title"><h1>📍 Acompanhar pedidos</h1><p>Pedidos desta demonstração, guardados apenas neste navegador.</p></div><div class="stack">${DB.orders.length?DB.orders.slice(0,30).map(o=>`<div class="panel"><div class="staff-header"><div><h3>${esc(o.code)} · ${esc(UNITS[o.unit])}</h3><p class="muted tiny">${esc(o.created)} · ${o.delivery==='retirada'?'Retirada':'Entrega'} · ${money(o.total+o.fee)}</p></div><span class="status ${stCls(o.status)}">${statusLabel(o.status)}</span></div>${o.bingoCardId?`<p class="tiny" style="margin-top:8px;color:#d8c8ff">🎟️ Você ganhou a cartela <b>${DB.bingo.cards.find(x=>x.id===o.bingoCardId)?.code||""}</b> do Bingo de Sexta! <button type="button" class="link-btn" data-action="bingo">Ver prêmios</button></p>`:o.delivery==="entrega"&&o.status!=="cancelado"?`<p class="tiny muted" style="margin-top:8px">🎟️ Ao receber, você ganha 1 cartela do Bingo de Sexta.</p>`:""}<div class="track-line">${['pendente','aprovado','separando','pronto','em_rota','entregue'].map((s,i)=>`<span class="${['pendente','aprovado','separando','pronto','em_rota','entregue'].indexOf(o.status)>=i?'done':''}">${statusLabel(s)}</span>`).join('')}</div></div>`).join(''):`<div class="panel empty-state"><strong>Você ainda não tem pedidos</strong><p>Adicione produtos e teste uma compra!</p>${button('Ir ao catálogo','catalog','button',`data-go="catalog"`)}</div>`}</div></div>`}
function statusLabel(s){return ({pendente:'Aguardando aprovação K10',aprovado:'Aprovado',separando:'Separando',pronto:'Pronto',em_rota:'Saiu para entrega',entregue:'Entregue',retirado:'Retirado / vendido',cancelado:'Cancelado'})[s]||s}
function kpi(title,value,sub=''){return `<article class="kpi"><small>${title}</small><strong>${value}</strong><span>${sub}</span></article>`}
function staffDashboard(){const a=dashboardStats('k10'),b=dashboardStats('k11'),orders=DB.orders;return `<h2>👑 Painel CEO K10</h2>${notice('Receita e lucro abaixo contabilizam apenas vendas concluídas. <b>Lucro bruto estimado</b> = receita dos produtos − custo cadastrado; não inclui impostos, taxas ou despesas fixas. Se faltar custo, mostra “Incompleto”.')}<div class="kpi-grid">${kpi('Vendas K10',money(a.revenue),a.orders+' pedidos concluídos')}${kpi('Vendas K11',money(b.revenue),b.orders+' vendas concluídas')}${kpi('Lucro bruto K10',a.profit===null?'Incompleto':money(a.profit),'antes de despesas')}${kpi('Lucro bruto K11',b.profit===null?'Incompleto':money(b.profit),'antes de despesas')}</div><div class="two-column"><section class="panel"><h3>📊 Comparativo por unidade</h3><div class="table-wrap"><table class="data-table"><tr><th>Indicador</th><th>K10</th><th>K11</th></tr><tr><td>Pedidos concluídos</td><td>${a.orders}</td><td>${b.orders}</td></tr><tr><td>Faturamento de produtos</td><td>${money(a.revenue)}</td><td>${money(b.revenue)}</td></tr><tr><td>Ticket médio</td><td>${money(a.ticket)}</td><td>${money(b.ticket)}</td></tr><tr><td>Lucro bruto estimado</td><td>${a.profit===null?'Custo ausente':money(a.profit)}</td><td>${b.profit===null?'Custo ausente':money(b.profit)}</td></tr></table></div></section><section class="panel"><h3>📦 Atenção gerencial</h3><div class="stack"><p class="muted tiny">${orders.filter(o=>o.status==='pendente').length} pedidos aguardando aprovação · ${DB.customers.filter(c=>c.status==='pendente').length} clientes aguardando validação.</p><p class="muted tiny">${DB.transfers.length} transferências K10 → K11 registradas.</p><p class="muted tiny">${DB.shifts.filter(s=>!s.closed).length} caixa(s) aberto(s) na K11.</p><p class="muted tiny">${DB.products.filter(p=>p.cost===null).length} produtos ainda sem custo de compra informado.</p></div>${button('Analisar pedidos','tab','button red',`data-id="orders"`)}</section></div>${DB.debts.some(d=>!d.paid)?notice(`⏳ <b>${DB.debts.filter(d=>!d.paid).length} venda(s) não paga(s)</b> na K11 · ${money(DB.debts.filter(d=>!d.paid).reduce((s,d)=>s+d.total,0))}. <button type="button" class="link-btn" data-action="tab" data-id="pending">Ver pendências</button>`,'red'):''}${staffFinance()}${staffTopProducts()}`}
function staffTopProducts(){const sales={k10:Object.create(null),k11:Object.create(null)};for(const o of DB.orders.filter(o=>['entregue','retirado'].includes(o.status))){if(o.unit!=='k10'&&o.unit!=='k11')continue;for(const [id,q] of Object.entries(o.needs||{}))sales[o.unit][id]=(sales[o.unit][id]||0)+(Number(q)||0)}return `<h3 class="dashboard-sub">Produtos mais vendidos</h3><div class="grid2">${['k10','k11'].map(u=>`<section class="panel"><h3>${UNITS[u]}</h3>${Object.entries(sales[u]).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([id,n])=>`<div class="summary"><span>${esc(item(id)?.name||id)}</span><b>${n} un.</b></div>`).join('')||'<p class="muted tiny">Ainda não há vendas concluídas.</p>'}</section>`).join('')}</div>`}
function staffProducts(){const ps=DB.products.filter(p=>!staffProductQuery||plain(p.name+' '+p.category).includes(plain(staffProductQuery)));return `<section class="panel"><h2>📋 Preços K10 × K11 e margens</h2><p class="page-summary">Cada unidade possui seu próprio preço de venda. Alterar K10 <b>não</b> muda K11. Os reajustes iniciais da filial são apenas exemplos editáveis.</p><div class="toolbar"><input class="input" id="productSearch" placeholder="Buscar pelo nome" style="width:270px" value="${esc(staffProductQuery)}">${button('Exportar preços Excel','export-products','button small')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th><th>Custo</th><th>Preço K10</th><th>Margem K10</th><th>Preço K11</th><th>Margem K11</th><th>Ajustar</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${productPhoto(p.id)} ${esc(p.name)}</td><td>${costLabel(p)}</td><td class="table-price">${money(p.price10)}</td><td>${grossMargin(p,'k10')===null?'—':grossMargin(p,'k10').toFixed(1)+'%'}</td><td class="table-price">${money(p.price11)}</td><td>${grossMargin(p,'k11')===null?'—':grossMargin(p,'k11').toFixed(1)+'%'}</td><td>${button('Editar','edit-product','mini-btn',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`}
function editProductModal(id){const p=item(id);if(!admin()||!p)return;popup('Editar produto · '+p.name,`<form id="editProductForm" class="stack"><input type="hidden" name="id" value="${esc(p.id)}"><div class="grid2"><label class="field">Preço custo unitário (R$)<input name="cost" placeholder="Ainda não informado" type="text" value="${p.cost===null?'':(p.cost/100).toFixed(2).replace('.',',')}"></label><label class="field">Preço K10 (R$)<input name="price10" required value="${(p.price10/100).toFixed(2).replace('.',',')}"></label><label class="field">Preço K11 (R$)<input name="price11" required value="${(p.price11/100).toFixed(2).replace('.',',')}"></label><label class="field">Contagem / ajuste estoque K10<input name="stock10" type="number" min="0" placeholder="Não informado" value="${p.stock10??''}"></label><label class="field">Contagem inicial / ajuste K11<input name="stock11" type="number" min="0" value="${p.stock11}"></label><label class="field">Ativo<select name="active"><option value="1" ${p.active?'selected':''}>Sim</option><option value="0" ${!p.active?'selected':''}>Não</option></select></label></div>${notice('Alterar quantidade é um ajuste manual registrado no histórico. Para enviar mercadoria da K10 para a K11, use a aba Transferências, que gera comprovante e debita a matriz.') }<button type="submit" class="button block">Salvar produto</button></form>`)}
function latestTransferItems(t){return t.items.map(i=>`${i.qty} × ${item(i.id)?.name||i.id}`).join(', ')}
function staffInventory(){const isAdmin=admin();const ps=DB.products;return `<div class="page-title"><h2>📦 ${isAdmin?'Estoque e transferências K10 → K11':'Estoque da filial K11'}</h2><p>${isAdmin?'A matriz administra toda mercadoria enviada à filial.':'A filial visualiza saldos, mas apenas o CEO ajusta quantidades e envia transferências.'}</p></div>${isAdmin?`<div class="two-column"><section class="panel stack"><h3>🚚 Registrar transferência</h3>${notice('A K10 só poderá transferir unidades cujo estoque tenha sido informado e seja suficiente. Lance a contagem real da K10 antes.') }<form id="transferForm" class="stack"><label class="field">Produto<select name="id" required>${ps.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · K10: ${fmtQty(p,'k10')} un.</option>`).join('')}</select></label><label class="field">Quantidade para enviar<input name="qty" type="number" required min="1" step="1" placeholder="Ex.: 24"></label><label class="field">Observação / responsável<input name="note" placeholder="Ex.: reposição de sexta-feira"></label><button type="submit" class="button">Registrar e gerar relatório</button></form></section><section class="panel"><h3>Transferências recentes</h3>${DB.transfers.length?DB.transfers.slice(0,7).map(t=>`<div class="summary"><span>${esc(t.created)}<br><small>${esc(latestTransferItems(t))}</small></span>${button('Recibo','print-transfer','mini-btn',`data-id="${t.id}"`)}</div>`).join(''):'<p class="muted tiny">Nenhuma transferência registrada.</p>'}</section></div>`:''}${isAdmin?transferImportPanel():''}<section class="panel"><h3>Saldo de cada unidade</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th>${isAdmin?'<th>Estoque K10</th>':''}<th>Estoque K11</th>${isAdmin?'<th>Custo unitário</th><th>Ajustar</th>':''}</tr></thead><tbody>${ps.map(p=>`<tr><td>${esc(p.name)}</td>${isAdmin?`<td>${fmtQty(p,'k10')}</td>`:''}<td>${fmtQty(p,'k11')}</td>${isAdmin?`<td>${costLabel(p)}</td><td>${button('Editar','edit-product','mini-btn',`data-id="${p.id}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div></section>`}
function staffCount(){const weekEnd=new Date(weekStart+'T12:00:00');weekEnd.setDate(weekEnd.getDate()+7);const endKey=[weekEnd.getFullYear(),String(weekEnd.getMonth()+1).padStart(2,'0'),String(weekEnd.getDate()).padStart(2,'0')].join('-');const inWeek=k=>k>=weekStart&&k<endKey;const ts=DB.transfers.filter(t=>inWeek(t.dateKey||'')),orders=DB.orders.filter(o=>o.unit==='k11'&&orderActive(o)&&inWeek(o.dateKey)),sold=orders.filter(o=>['retirado','entregue'].includes(o.status)),reserved=orders.filter(o=>!['retirado','entregue'].includes(o.status)),products=DB.products;return `<div class="page-title"><h2>🧮 Contagem e conferência semanal K11</h2><p>Compare vendas, reservas e mercadorias recebidas na filial na semana escolhida.</p></div>${notice('Saldo esperado no sistema inclui contagem inicial, todas as transferências, vendas e ajustes. O relatório semanal separa <b>vendas concluídas</b> de <b>pedidos reservados</b>. A contagem física permite registrar divergências sem alterar estoque automaticamente.')}<div class="toolbar"><label class="field">Semana de referência (data inicial)<input id="weekStart" type="date" value="${weekStart}" /></label><span class="muted tiny">De ${esc(weekStart)} a ${esc(endKey)} (fim exclusivo)</span></div><div class="grid2"><section class="panel"><h3>Contagens registradas</h3>${DB.counts.length?DB.counts.slice(0,6).map(c=>`<div class="summary"><span>${esc(c.created)} · ${esc(c.name)} · físico ${c.actual} / sistema ${c.expected}</span><b class="${c.diff===0?'green-text':'red-text'}">${c.diff>0?'+':''}${c.diff}</b></div>`).join(''):'<p class="muted tiny">Comece preenchendo as quantidades reais.</p>'}</section><section class="panel"><h3>Resumo da semana</h3><p class="muted tiny">Transferências recebidas: <b>${ts.length}</b></p><p class="muted tiny">Vendas concluídas K11: <b>${sold.length}</b></p><p class="muted tiny">Pedidos ainda reservados: <b>${reserved.length}</b></p><p class="muted tiny">A conferência física não altera automaticamente o estoque: a matriz aprova ajustes.</p></section></div><section class="panel"><h3>Relatório por produto · K11</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th><th>Recebido semana</th><th>Vendido semana</th><th>Reservado semana</th><th>Saldo no sistema</th><th>Físico contado</th><th>Conferir</th></tr></thead><tbody>${products.map(p=>{const received=ts.reduce((s,t)=>s+t.items.filter(i=>i.id===p.id).reduce((a,i)=>a+i.qty,0),0),soldQ=sold.reduce((s,o)=>s+(o.needs[p.id]||0),0),reservedQ=reserved.reduce((s,o)=>s+(o.needs[p.id]||0),0);return `<tr><td>${esc(p.name)}</td><td>${received}</td><td>${soldQ}</td><td>${reservedQ}</td><td><b>${p.stock11}</b></td><td><input type="number" id="count-${p.id}" min="0" placeholder="Físico" aria-label="Contagem real ${esc(p.name)}"></td><td>${button('Conferir','count-product','mini-btn',`data-id="${p.id}"`)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function orderRow(o,u){const names=o.lines.map(l=>`${l.q}× ${l.name}`).join(', '),isDriver=user()?.role==='driver',canManage=admin()||seller()&&o.unit==='k11';return `<article class="panel"><div class="staff-header"><div><h3>${esc(o.code)} · ${esc(UNITS[o.unit])}</h3><p class="muted tiny">${esc(o.created)} · ${esc(o.origin==='pdv'?'Venda balcão':'Pedido site')} · ${esc(o.delivery)}</p></div><span class="status ${stCls(o.status)}">${statusLabel(o.status)}</span></div><p class="tiny" style="margin:9px 0;color:#dad8df">${esc(names)}</p><p class="muted tiny">Cliente: ${esc(o.customer?.name||'Venda sem cadastro')} ${o.customer?.phone?'· '+esc(o.customer.phone):''} ${o.customer?.neighborhood?'· '+esc(o.customer.neighborhood):''}</p><p class="muted tiny">Vendedor: ${esc(DB.users.find(x=>x.id===o.sellerId)?.name||'Loja online')} · Total: <b>${money(o.total+o.fee)}</b></p>${o.delivery==='entrega'&&(isDriver||admin())&&o.status!=='cancelado'?routeButtons(o):''}<div class="form-actions" style="margin-top:13px">${button('🖨️ Imprimir','print-order','button small dark',`data-id="${esc(o.id)}"`)}${canManage&&o.status==='pendente'&&admin()?button('✓ Aprovar','change-status','button small',`data-id="${esc(o.id)}" data-value="aprovado"`):''}${admin()&&['aprovado','separando'].includes(o.status)?button('Pronto','change-status','button small',`data-id="${esc(o.id)}" data-value="pronto"`):''}${admin()&&['pronto'].includes(o.status)?button('Saiu para entrega','change-status','button small',`data-id="${esc(o.id)}" data-value="em_rota"`):''}${(admin()||isDriver)&&o.status==='em_rota'?button('✓ Entregue','change-status','button small',`data-id="${esc(o.id)}" data-value="entregue"`):''}${admin()&&['pendente','aprovado','separando','pronto','em_rota'].includes(o.status)?button('Cancelar','change-status','button small dark',`data-id="${esc(o.id)}" data-value="cancelado"`):''}${isDriver&&o.driverId===null?button('Assumir entrega','assign-self','button small',`data-id="${esc(o.id)}"`):''}</div></article>`}
function staffOrders(){let os=DB.orders;if(seller())os=os.filter(o=>o.unit==='k11');if(user()?.role==='driver')os=os.filter(o=>o.delivery==='entrega'&&['aprovado','separando','pronto','em_rota','entregue'].includes(o.status)&&(o.driverId===null||o.driverId===user().id));if(filterOrder!=='todos')os=os.filter(o=>o.status===filterOrder);return `<div class="page-title"><h2>${user()?.role==='driver'?'🛵 Painel do motorista':'📦 Pedidos da operação'}</h2><p>Entregas novas passam pela aprovação da matriz antes de seguirem ao motorista.</p></div><div class="toolbar"><select class="input" id="orderFilter" style="width:230px"><option value="todos">Todos os status</option>${['pendente','aprovado','separando','pronto','em_rota','entregue','retirado','cancelado'].map(x=>`<option value="${x}" ${filterOrder===x?'selected':''}>${statusLabel(x)}</option>`).join('')}</select></div>${os.length?`<div class="grid2">${os.map(o=>orderRow(o)).join('')}</div>`:`<div class="panel empty-state"><strong>Não há pedidos nesse filtro</strong><p>As vendas novas vão aparecer aqui.</p></div>`}`}
function staffCash(){const u=user(),shifts=DB.shifts.filter(s=>admin()||s.userId===u.id),active=seller()?currentShift(u.id):null;return `<div class="page-title"><h2>💰 ${seller()?'Caixa do atendente':'Controle de caixas da K11'}</h2><p>Cada atendente tem sua própria abertura, recebimentos e fechamento para apurar diferenças.</p></div>${seller()?`<section class="panel stack">${active?`<h3>Caixa aberto desde ${esc(active.opened)}</h3><p>Troco inicial: ${money(active.opening)} · ${esc(u.name)}</p>${button('Fechar meu caixa','close-shift','button red')}`:`<form id="openShiftForm" class="stack"><h3>Abrir caixa do meu turno</h3><label class="field">Dinheiro de abertura / troco (R$)<input name="opening" required placeholder="0,00"></label><button type="submit" class="button">Abrir caixa · ${esc(u.name)}</button></form>`}</section>`:''}<section class="panel"><h3>Histórico da K11</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Vendedor</th><th>Abertura</th><th>Estado</th><th>Dinheiro esperado</th><th>Dinheiro contado</th><th>Diferença</th></tr></thead><tbody>${shifts.map(s=>{const cashSales=DB.orders.filter(o=>o.shiftId===s.id&&o.payment==='dinheiro'&&['retirado','entregue'].includes(o.status)).reduce((a,o)=>a+o.total+o.fee,0),expected=s.opening+cashSales;return `<tr><td>${esc(DB.users.find(u=>u.id===s.userId)?.name||'Atendente')}</td><td>${esc(s.opened)}<br>${money(s.opening)}</td><td><span class="pill ${s.closed?'ok':'warning'}">${s.closed?'Fechado':'Aberto'}</span></td><td>${money(expected)}</td><td>${s.counted===null?'—':money(s.counted)}</td><td>${s.counted===null?'—':`<b class="${s.counted-expected<0?'red-text':'green-text'}">${money(s.counted-expected)}</b>`}</td></tr>`}).join('')}</tbody></table></div></section>`}
function staffCombos(){return `<div class="page-title"><h2>🎁 Gestão de combos</h2><p>Ative ou pause a divulgação. Preços são independentes dos produtos vendidos separadamente.</p></div><div class="grid2">${DB.combos.map(c=>`<section class="panel"><div class="staff-header"><div><h3>${esc(c.name)}</h3><p class="tiny muted">${esc(c.description)}</p></div><span class="pill ${c.enabled?'ok':'bad'}">${c.enabled?'Ativo':'Pausado'}</span></div><div class="summary"><span>Preço sugerido</span><b>${money(c.price)}</b></div><div class="summary"><span>Custo dos componentes</span><b>${comboCost(c)===null?'Faltam custos':money(comboCost(c))}</b></div><div class="form-actions">${button('Editar preço','edit-combo','button small',`data-id="${esc(c.id)}"`)}${button(c.enabled?'Pausar':'Ativar','toggle-combo','button small dark',`data-id="${esc(c.id)}"`)}</div></section>`).join('')}</div>`}
let posCart={},posMode='retirada',posPayment='dinheiro';
function staffExcel(){return `<div class="page-title"><h2>📊 Importar e exportar Excel</h2><p>Ajuste custos e preços das unidades em planilhas independentes.</p></div><div class="two-column"><section class="panel stack"><h3>Importar mercadorias</h3>${notice('Aceita <b>.xlsx e .csv</b>. Reconhece “Produto” ou “ID”, “Custo”, “Preço K10”, “Preço K11”, “Estoque K10”, “Estoque K11”. Nunca interpreta “Venda no mês” como estoque.') }<label class="field">Arquivo Excel ou CSV<input type="file" id="importFile" accept=".xlsx,.csv"></label><label class="field">Atualizar quais preços?<select id="importUnit"><option value="k10">Apenas K10</option><option value="k11">Apenas K11</option><option value="both">K10 e K11 (colunas separadas)</option></select></label>${importData?`<div class="file-note">Arquivo lido: ${esc(importData.filename)} · ${importData.rows.length} linhas · ${importData.matches.length} produtos identificados · ${importData.unknown.length} linhas não identificadas.</div><div class="table-wrap"><table class="data-table"><tr><th>Produto</th><th>Preço K10</th><th>Preço K11</th><th>Custo</th></tr>${importData.matches.slice(0,8).map(x=>`<tr><td>${esc(x.product.name)}</td><td>${esc(x.row.price10??'—')}</td><td>${esc(x.row.price11??'—')}</td><td>${esc(x.row.cost??'—')}</td></tr>`).join('')}</table></div>${button('✓ Conferir e aplicar atualização','apply-import','button block')}`:'<p class="tiny muted">Selecione uma planilha para ver a prévia antes de aplicar.</p>'}</section><section class="panel stack"><h3>Exportar planilhas</h3><div class="file-note"><b>⭐ Planilha de gestão K10 + K11</b><br>Resumo do mês, vendas, margens, lucro, gastos, fiado e transferências, prontos para gestão.</div><label class="field">Mês<input type="month" id="expMonth" value="${expMonth}"></label>${button('⬇️ Baixar planilha de gestão','export-gestao','button block')}${button('⬇️ Modelo de transferência K10 → K11','transfer-template','button dark block')}<p class="muted tiny">Cada unidade tem uma aba separada com seu preço de venda, margem estimada e estoque.</p>${button('⬇️ Baixar Excel com K10 + K11','export-products','button block')}${button('⬇️ Relatório de vendas Excel','export-sales','button dark block')}${button('⬇️ Transferências Excel','export-transfers','button dark block')}${button('↩️ Exportar backup dos dados','backup','button dark block')}${notice('Na visualização do Claude, os arquivos baixados podem depender das permissões do navegador. Se falhar, use o projeto no Chrome ou no servidor.')}</section></div>`}
function getReceipt(o){const title=o.type==='transfer'?'TRANSFERÊNCIA K10 → K11':`${o.unit==='k11'?'K11 BAR':'K10 DELIVERY'} · PEDIDO`;const lines=o.type==='transfer'?o.items.map(i=>`<div>${i.qty} × ${esc(item(i.id)?.name||i.id)}</div>`).join(''):o.lines.map(l=>`<div>${Number(l.q)||0} × ${esc(l.name)} <span style="float:right">${money(l.price*l.q)}</span></div>`).join('');return `<div class="receipt-preview"><h2>${title}</h2><div style="text-align:center">${esc(o.code)} · ${esc(o.created)}</div><hr>${o.type==='transfer'?`Origem: K10 · Destino: K11<br>Observação: ${esc(o.note||'—')}`:`Atendimento: ${esc(DB.users.find(u=>u.id===o.sellerId)?.name||'Online')}<br>Modalidade: ${esc(o.delivery)}<br>Cliente: ${esc(o.customer?.name||'Venda balcão')}<br>${o.delivery==='entrega'?`Telefone: ${esc(o.customer?.phone||'')}<br>Endereço: ${esc([o.customer?.street,o.customer?.number,o.customer?.neighborhood].filter(Boolean).join(', '))}<br>`:''}Pagamento: ${esc(o.payment)}`}<hr>${lines}<hr><b>${o.type==='transfer'?'Quantidade total: '+o.items.reduce((s,i)=>s+i.qty,0):'TOTAL: '+money(o.total+o.fee)}</b><hr><small>Comprovante de pedido · não é documento fiscal</small></div>`}
function printReceipt(o){pendingPrintId=o.id;$('#receipt-print').innerHTML=getReceipt(o);popup('🖨️ Comprovante para impressão',`${getReceipt(o)}<div class="form-actions">${button('Imprimir agora','run-print','button block')}${button('Fechar','close','button dark block')}</div>`)}
function customerOfForm(fd){return{name:String(fd.get('name')||'').trim(),phone:String(fd.get('phone')||'').trim(),street:String(fd.get('street')||'').trim(),number:String(fd.get('number')||'').trim(),neighborhood:String(fd.get('neighborhood')||'').trim(),reference:String(fd.get('reference')||'').trim()}}
function render(){const el=$('#app');if(!el)return;portalGuard();el.innerHTML=({home,catalog,cart:cartPage,checkout,tracking:trackPage,staff,account:accountPage,terms:termsPage,bingo:bingoPage})[view]?.()||home();footerFill();headerFill();restoreDrafts();$('#cartBadge').textContent=cartCount();$('#mobileBadge').textContent=cartCount();$$('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===view));const s=$('#search');if(s&&document.activeElement!==s)s.value=search;}
async function readFile(file){if(file.size>12e6)throw Error('Limite de 12 MB por arquivo.');let sheets;if(file.name.toLowerCase().endsWith('.xlsx'))sheets=await readXlsx(file);else if(file.name.toLowerCase().endsWith('.csv'))sheets=[{name:'CSV',rows:readCsv(await file.text())}];else throw Error('Envie XLSX ou CSV.');let rows=[];for(const sheet of sheets){if(!sheet.rows?.length)continue;const found=normalizeImported(sheet.rows);rows.push(...found.map(x=>({...x,sheet:sheet.name})))}if(!rows.length)throw Error('Nenhuma tabela com coluna Produto/ID foi encontrada.');const matches=[],unknown=[];for(const r of rows){let prod=DB.products.find(p=>p.id===r.id)||DB.products.find(p=>plain(p.name)===plain(r.name));if(prod)matches.push({product:prod,row:r});else unknown.push(r.name||r.id)}return {filename:file.name,rows,matches,unknown};}
function readCsv(text){text=text.replace(/^\ufeff/,'');const separator=(text.split(/\r?\n/)[0].match(/;/g)||[]).length>=(text.split(/\r?\n/)[0].match(/,/g)||[]).length?';':',';let rows=[],cur=[],field='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++}else quote=!quote}else if(!quote&&c===separator){cur.push(field);field=''}else if(!quote&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;cur.push(field);if(cur.some(x=>x.trim()))rows.push(cur);cur=[];field=''}else field+=c}cur.push(field);if(cur.some(x=>x.trim()))rows.push(cur);return rows;}
async function readXlsx(file){if(typeof JSZip==='undefined')throw Error('Biblioteca de planilha não carregou.');const zip=await JSZip.loadAsync(file),parser=new DOMParser();const xml=async path=>{const f=zip.file(path);return f?parser.parseFromString(await f.async('string'),'application/xml'):null};const shared=await xml('xl/sharedStrings.xml'),ss=shared?Array.from(shared.getElementsByTagName('si')).map(x=>x.textContent):[];const targets=Object.keys(zip.files).filter(x=>/^xl\/worksheets\/sheet\d+\.xml$/.test(x)).sort();const sheets=[];for(const f of targets.slice(0,10)){let doc=await xml(f);if(!doc)continue;const rws=[];for(const row of Array.from(doc.getElementsByTagName('row')).slice(0,1500)){let fields=[];for(const c of Array.from(row.getElementsByTagName('c'))){const ref=c.getAttribute('r')||'A1',letters=(ref.match(/^[A-Z]+/)||['A'])[0];let ix=0;for(const ch of letters)ix=ix*26+ch.charCodeAt(0)-64;ix--;const typ=c.getAttribute('t'),v=c.getElementsByTagName('v')[0]?.textContent||'',is=c.getElementsByTagName('is')[0]?.textContent||'';fields[ix]=typ==='s'?ss[Number(v)]||'':typ==='inlineStr'?is:v;}rws.push(fields)}sheets.push({name:f.split('/').pop(),rows:rws})}return sheets;}
function normalizeImported(rows){let headerIndex=rows.findIndex((r,i)=>i<15&&r.some(c=>['produto','mercadoria','product','id','codigo','código'].includes(plain(c))));if(headerIndex<0)return [];const h=rows[headerIndex].map(x=>plain(x));let col=()=>{};const get=(r,names)=>{const ix=h.findIndex(t=>names.includes(t));return ix<0?null:(r[ix]??null)};
 return rows.slice(headerIndex+1).map(r=>({id:get(r,['id','codigo','código','sku']),name:get(r,['produto','mercadoria','product','nome']),cost:get(r,['custo','preco de custo','custo unitario','custo un.','custo un','custo unitarío']),price10:get(r,['preco k10','preço k10','preco venda k10','preco venda','preço venda','preco de venda','valor k10']),price11:get(r,['preco k11','preço k11','preco venda k11','preco filial','valor k11']),stock10:get(r,['estoque k10','estoque matriz','saldo k10']),stock11:get(r,['estoque k11','estoque filial','saldo k11'])})).filter(x=>x.id||x.name).filter(x=>!String(x.name||'').trim().startsWith('▸'));}
function applyImport(scope){if(!admin()||!importData)throw Error('Sem permissão ou planilha.');const changes=[],previous=[];for(const {product:p,row:r} of importData.matches){const change={};const isValid=x=>x!==null&&x!==undefined&&String(x).trim()!==''&&Number.isFinite(num(x));
 if(isValid(r.cost))change.cost=cents(r.cost);
 if((scope==='k10'||scope==='both')&&isValid(r.price10))change.price10=cents(r.price10);
 if((scope==='k11'||scope==='both')&&isValid(r.price11))change.price11=cents(r.price11);
 if((scope==='k10'||scope==='both')&&isValid(r.stock10))change.stock10=Math.max(0,Math.floor(num(r.stock10)));
 if((scope==='k11'||scope==='both')&&isValid(r.stock11))change.stock11=Math.max(0,Math.floor(num(r.stock11)));
 if(Object.keys(change).length){previous.push({id:p.id,before:Object.fromEntries(Object.keys(change).map(k=>[k,p[k]])),after:change});changes.push([p,change]);}}
 for(const [p,change] of changes){if(change.price10!==undefined&&change.price10<0||change.price11!==undefined&&change.price11<0||change.cost!==undefined&&change.cost<0)throw Error('Planilha contém valores inválidos.');}
 for(const [p,change] of changes){if(change.stock10!==undefined&&p.stock10!==change.stock10||change.stock11!==undefined&&p.stock11!==change.stock11)DB.stockEvents.push({id:uid(),date:now(),productId:p.id,type:'import',before10:p.stock10,before11:p.stock11,change});Object.assign(p,change)}DB.lastImport={date:now(),file:importData.filename,changes:previous};save();const count=changes.length;importData=null;toast(`Atualização aplicada em ${count} produto(s).`);render();}
function workbookSheets(kind){let titles=[],data=[];if(kind==='products'){titles=['K10','K11'];for(const u of ['k10','k11'])data.push([['ID','Produto','Categoria','Custo','Preço '+u.toUpperCase(),'Estoque '+u.toUpperCase(),'Margem %'],...DB.products.map(p=>[p.id,p.name,p.category,p.cost===null?'':p.cost/100,price(p,u)/100,(u==='k10'?p.stock10:p.stock11)??'',grossMargin(p,u)===null?'':Math.round(grossMargin(p,u)*100)/100])]);}else if(kind==='sales'){titles=['Vendas'];data=[[['Código','Unidade','Data','Vendedor','Status','Pagamento','Itens','Total de produtos','Custo total','Lucro bruto estimado'],...DB.orders.map(o=>[o.code,o.unit,o.created,DB.users.find(x=>x.id===o.sellerId)?.name||'Online',o.status,o.payment,o.lines.map(l=>l.name+' x'+l.q).join(' / '),o.total/100,orderProfit(o)===null?'':(o.total-orderProfit(o))/100,orderProfit(o)===null?'':orderProfit(o)/100])]];}else{titles=['Transferências'];data=[[['Código','Data','Produto','Quantidade','Origem','Destino','Observação'],...DB.transfers.flatMap(t=>t.items.map(i=>[t.code,t.created,item(i.id)?.name||i.id,i.qty,'K10','K11',t.note]))]];}return{titles,data}}
function xmlEscape(s){return String(s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\uFFFE\uFFFF]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
async function exportXlsx(kind){if(typeof JSZip==='undefined')throw Error('Leitor Excel indisponível.');const {titles,data}=workbookSheets(kind),zip=new JSZip(),cells=rows=>rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>{let n=j+1,letters='';while(n){n--;letters=String.fromCharCode(65+n%26)+letters;n=Math.floor(n/26)}return v===null||v===undefined?'':typeof v==='number'&&Number.isFinite(v)?`<c r="${letters}${i+1}"><v>${v}</v></c>`:`<c r="${letters}${i+1}" t="inlineStr"><is><t>${xmlEscape(v)}</t></is></c>`}).join('')}</row>`).join('');const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';zip.file('[Content_Types].xml',`<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${titles.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`);zip.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml',`<?xml version="1.0"?><workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${titles.map((t,i)=>`<sheet name="${xmlEscape(t)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`);zip.file('xl/_rels/workbook.xml.rels',`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${titles.map((t,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`);data.forEach((rows,i)=>zip.file(`xl/worksheets/sheet${i+1}.xml`,`<?xml version="1.0"?><worksheet xmlns="${ns}"><sheetData>${cells(rows)}</sheetData></worksheet>`));await downloadBlob(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),`K10_K11_${kind}_${diaCuiaba()}.xlsx`);toast('Planilha Excel exportada.');}
async function downloadBlob(blob,name){try{const dl=window.claude&&await window.claude.use('downloads');if(dl){await dl.save({filename:name,data:blob});return}}catch(err){if(err&&err.code==='declined')return;}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function executeAction(el){const a=el.dataset.action,id=el.dataset.id,val=el.dataset.value;if(!a)return;
 if(a==='backdrop'){closeModal();return}
 if(a==='close'){closeModal();return}
 if(['home','catalog','cart','checkout','tracking','staff'].includes(a)){go(a);return}
 if(a==='combos'){go('home');setTimeout(()=>$('#combos')?.scrollIntoView({behavior:'smooth'}),60);return}
 if(a==='cat'){category=val;search='';go('catalog');return}
 if(a==='reset-catalog'){category='Todas';search='';go('catalog');return}
 if(a==='add'){changeCart(id,1);return}
 if(a==='qty'){changeCart(id,Number(el.dataset.delta));return}
 if(a==='clear-cart'){if(el.dataset.ok!=='1'){el.dataset.ok='1';el.textContent='Toque de novo para limpar';setTimeout(()=>{if(el.isConnected){el.dataset.ok='';el.textContent='Limpar carrinho'}},4000);return}cart={};saveCart();render();return}
 if(a==='choose-mode'){mode=val;render();return}
 if(a==='choose-pay'){payment=val;render();return}
 if(a==='choose-paywhen'){payWhen=val==='entrega'?'entrega':'agora';if(payWhen==='agora'&&payment==='dinheiro')payment='pix';render();return}
 if(a==='scroll-combos'){const rail=$('#comboRail');rail?.scrollBy({left:Number(el.dataset.direction)*265,behavior:'smooth'});return}
 if(a==='login'&&false){const u=DB.users.find(u=>u.id===id&&u.active);if(!u)throw Error('Usuário desativado.');DB.activeUser=u.id;staffTab=u.role==='admin'?'dashboard':u.role==='seller'?'pos':'orders';save();go('staff');return}
 if(a==='logout'){DB.activeUser=null;save();staffTab='dashboard';go('staff');return}
 if(a==='tab'){staffTab=id;staffProductQuery='';render();return}
 if(a==='edit-product'){editProductModal(id);return}
 if(a==='edit-combo'){if(!admin())return;const c=DB.combos.find(x=>x.id===id);popup('Editar combo · '+c.name,`<form id="comboForm" class="stack"><input type="hidden" name="id" value="${esc(c.id)}"><label class="field">Preço promocional (R$)<input name="price" required value="${(c.price/100).toFixed(2).replace('.',',')}"></label>${notice('Confira se a promoção cobre o custo dos produtos e as despesas antes de divulgar.') }<button class="button" type="submit">Salvar preço do combo</button></form>`);return}
 if(a==='toggle-combo'){if(!admin())throw Error('Apenas CEO K10.');const c=DB.combos.find(x=>x.id===id);c.enabled=!c.enabled;save();render();return}
 if(a==='pos-add'){if(!seller())throw Error('Área de vendas K11.');const selected=$('#posProduct')?.value;if(!selected)throw Error('Selecione um produto.');const p=item(selected);if(!available(p,'k11',(posCart[selected]||0)+1))throw Error('Estoque K11 insuficiente. Faça uma transferência primeiro.');posCart[selected]=(posCart[selected]||0)+1;render();return}
 if(a==='pos-qty'){let q=Math.max(0,(posCart[id]||0)+Number(el.dataset.delta));if(q&&!available(item(id),'k11',q))throw Error('Estoque da K11 insuficiente.');if(q)posCart[id]=q;else delete posCart[id];render();return}
 if(a==='pos-mode'){posMode=val;render();return}
 if(a==='print-order'){const o=DB.orders.find(x=>x.id===id);if(o)printReceipt(o);return}
 if(a==='print-transfer'){const t=DB.transfers.find(x=>x.id===id);if(t)printReceipt({...t,type:'transfer'});return}
 if(a==='run-print'){try{window.print()}catch(err){toast('Impressão bloqueada nesta visualização. Use o arquivo no Chrome.',true)}return}
 if(a==='change-status'){if(!admin()&&!(user()?.role==='driver'&&val==='entregue'))throw Error('Sem permissão para mudar esse status.');const o=DB.orders.find(x=>x.id===id);if(!o)throw Error('Pedido não encontrado.');if(user()?.role==='driver'&&(o.driverId!==user().id||o.status!=='em_rota'))throw Error('Entrega deve ser atribuída antes.');changeStatus(o,val);render();return}
 if(a==='assign-self'){if(user()?.role!=='driver')throw Error('Somente motorista.');const o=DB.orders.find(x=>x.id===id);if(!o||o.driverId!==null||!['aprovado','separando','pronto','em_rota'].includes(o.status))throw Error('Entrega indisponível.');o.driverId=user().id;save();render();return}
 if(a==='approve-customer'){if(!admin())throw Error('Apenas CEO K10.');const c=DB.customers.find(c=>c.id===id);if(c)c.status='aprovado';save();render();return}
 if(a==='count-product'){if(!admin())throw Error('Apenas CEO K10.');const p=item(id),input=$(`#count-${CSS.escape(id)}`);if(!input||input.value==='')throw Error('Preencha a contagem física antes de conferir.');const actual=Number(input.value);if(!Number.isInteger(actual)||actual<0)throw Error('Quantidade inválida.');const rec={id:uid(),created:now(),productId:id,name:p.name,expected:p.stock11,actual,diff:actual-p.stock11};DB.counts.unshift(rec);save();if(rec.diff===0)toast('Estoque conferido: quantidade correta.');else popup('Diferença na conferência',`<p class="page-summary">${esc(p.name)}: sistema ${p.stock11} un. × contagem real ${actual} un. Diferença <b>${rec.diff>0?'+':''}${rec.diff}</b>.</p>${notice('Uma diferença pode indicar quebra, perda, entrada sem registro ou falha de lançamento. Confira antes de ajustar.')}${button('Aplicar ajuste físico','approve-count','button red',`data-id="${rec.id}"`)} ${button('Só registrar divergência','close','button dark')}`);renderIfClosed();return}
 if(a==='approve-count'){if(!admin())throw Error('Apenas CEO K10.');const c=DB.counts.find(x=>x.id===id);if(!c)throw Error('Contagem não encontrada.');if(c.applied)throw Error('Ajuste já aplicado.');const p=item(c.productId),previous=p.stock11;p.stock11=c.actual;DB.stockEvents.push({id:uid(),date:now(),productId:p.id,type:'count_adjustment',before11:previous,after11:p.stock11,user:user().name});c.applied=true;save();closeModal();render();toast('Ajuste de contagem realizado.');return}
 if(a==='close-shift'){if(!seller())throw Error('Apenas vendedor K11.');const s=currentShift(user().id);if(!s)throw Error('Nenhum caixa aberto.');const expected=s.opening+DB.orders.filter(o=>o.shiftId===s.id&&o.payment==='dinheiro'&&['retirado','entregue'].includes(o.status)).reduce((x,o)=>x+o.total+o.fee,0);popup('Fechar caixa · '+user().name,`<form id="closeShiftForm" class="stack">${notice('Dinheiro esperado: <b>'+money(expected)+'</b>. Confira fisicamente o valor e preencha o total contado.')}<label class="field">Dinheiro contado no caixa (R$)<input required name="counted" placeholder="Ex.: 250,00"></label><button class="button red" type="submit">Fechar e registrar diferença</button></form>`);return}
 if(a==='apply-import'){if(!admin())throw Error('Somente CEO K10.');if(!importData)throw Error('Escolha uma planilha.');const scope=$('#importUnit')?.value||'k10';popup('Confirmar importação',`<p class="page-summary">Atualizar <b>${importData.matches.length}</b> produtos no escopo <b>${esc(scope.toUpperCase())}</b>? Faça backup antes. O custo será aplicado quando informado.</p><div class="form-actions">${button('✓ Sim, aplicar','apply-import-ok','button red',`data-value="${esc(scope)}"`)}${button('Cancelar','close','button dark')}</div>`);return}
 if(a==='apply-import-ok'){if(!admin())throw Error('Somente CEO K10.');closeModal();applyImport(val||'k10');return}
 if(a==='export-products'){await exportXlsx('products');return}
 if(a==='export-sales'){await exportXlsx('sales');return}
 if(a==='export-transfers'){await exportXlsx('transfers');return}
 if(a==='backup'){await downloadBlob(new Blob([JSON.stringify(DB,null,2)],{type:'application/json'}),'K10_K11_backup_'+diaCuiaba()+'.json');toast('Backup local gerado.');return}
}
