function sha256(str){const r=(v,a)=>(v>>>a)|(v<<(32-a));const K=[],H=[];let n=2,c=0;const isP=x=>{for(let i=2;i*i<=x;i++)if(x%i===0)return false;return true};while(c<64){if(isP(n)){if(c<8)H[c]=(Math.pow(n,1/2)*4294967296)|0;K[c]=(Math.pow(n,1/3)*4294967296)|0;c++}n++}
 const by=new TextEncoder().encode(str),l=by.length,nW=(((l+8)>>6)+1)*16,w=new Array(nW).fill(0);for(let i=0;i<l;i++)w[i>>2]|=by[i]<<(24-(i%4)*8);w[l>>2]|=0x80<<(24-(l%4)*8);w[nW-1]=l*8;
 let h=H.slice();for(let j=0;j<nW;j+=16){const W=w.slice(j,j+16);let [a,b,cc,d,e,f,g,hh]=h;for(let i=0;i<64;i++){if(i>=16){const x=W[i-15],y=W[i-2];W[i]=(W[i-16]+(r(x,7)^r(x,18)^(x>>>3))+W[i-7]+(r(y,17)^r(y,19)^(y>>>10)))|0}const t1=(hh+(r(e,6)^r(e,11)^r(e,25))+((e&f)^(~e&g))+K[i]+W[i])|0,t2=((r(a,2)^r(a,13)^r(a,22))+((a&b)^(a&cc)^(b&cc)))|0;hh=g;g=f;f=e;e=(d+t1)|0;d=cc;cc=b;b=a;a=(t1+t2)|0}h=[a,b,cc,d,e,f,g,hh].map((v,k)=>(v+h[k])|0)}
 return h.map(v=>(v>>>0).toString(16).padStart(8,'0')).join('')}
