function pagamentoOnlineAtivo(){return !!(window.K10Pagamento&&window.K10_PAGAMENTO&&window.K10_PAGAMENTO.url)}
function pagarAgora(){return payWhen==='agora'&&pagamentoOnlineAtivo()}
function opStatus(o){return (o&&o.onlinePay&&o.onlinePay.status)||''}
function pagoOnline(o){return opStatus(o)==='pago'}
function podePagarOnline(o){return pagamentoOnlineAtivo()&&!!o&&o.origin==='site'&&o._sb==='ok'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(o.id))&&!['entregue','retirado','cancelado','finalizado'].includes(o.status)&&!['pago','divergente','duplicado'].includes(opStatus(o))&&!(o.onlinePay&&o.onlinePay.alert)}
function payInfoCli(o){const op=o.onlinePay,tot=o.total+o.fee;if(op&&op.status==='pago')return `✅ <b>Pago online</b> · ${op.method==='cartao'?'Cartão':'PIX'} · ${money(op.amount||tot)}`;if(op&&op.alert)return '⚠️ <b>Pagamento em conferência pela K10.</b> Não pague de novo: vamos resolver com você.';return payInfo(o).replace('levar','o entregador leva').replace('conferir o comprovante na entrega','pague na entrega').replace('levar a maquininha','maquininha na entrega')+(podePagarOnline(o)?`<div style="margin-top:8px">${button('💳 Pagar agora (Pix ou cartão)','pay-online','button small',`data-id="${esc(o.id)}"`)}</div>`:'')}
function paidField(o){if(pagoOnline(o))return '<input type="hidden" name="paid" value="1"><p class="pay-box" style="margin:0">✅ <b>Pago online pelo Mercado Pago.</b> Não cobre o cliente.</p>';return `<label class="check"><input type="checkbox" name="paid" required><span>Recebi o pagamento (${esc(payLabel(o.payment))}).</span></label>`+(pagamentoOnlineAtivo()?button('📲 Gerar Pix na hora (confirma sozinho)','pix-entrega','button small dark block',`data-id="${esc(o.id)}"`):'')}
function abrirPagamentoOnline(o,origem){if(!pagamentoOnlineAtivo())throw Error('Pagamento online indisponível agora. Tente de novo em instantes.');const naEntrega=origem==='entrega';
 window.K10Pagamento.abrir({pedidoId:o.id,codigo:o.code,origem:naEntrega?'entrega':'site',metodo:naEntrega?'pix':(o.payment==='cartao'?'cartao':'pix'),
  onPago:p=>{const m=(p&&p.metodo)==='cartao'?'cartao':'pix';o.onlinePay={status:'pago',method:m,amount:p?Math.round((+p.valor_pago||+p.valor||0)*100):o.total+o.fee,paidAt:(p&&p.pago_em)||new Date().toISOString(),provider:'mercadopago'};o.payment=m;save()},
  onFechar:s=>{if(naEntrega&&pagoOnline(o)){closeModal();newAction5({dataset:{action:o.delivery==='retirada'?'ord-picked':'ord-deliver',id:o.id}}).catch(()=>{});return}if(s==='pagar_na_entrega')toast('Tudo bem! Você paga na '+(o.delivery==='retirada'?'retirada':'entrega')+'.');try{render()}catch(e){}}})}
function payLabel(p){return({pix:'PIX',cartao:'Cartão',dinheiro:'Dinheiro',fiado:'Fiado (pendente)'})[p]||p}
function ageOf(s){const d=new Date(s+'T12:00:00');if(isNaN(d))return -1;const t=new Date();let a=t.getFullYear()-d.getFullYear();const m=t.getMonth()-d.getMonth();if(m<0||(m===0&&t.getDate()<d.getDate()))a--;return a}
function validCPF(v){const c=digits(v);if(c.length!==11||/^(\d)\1+$/.test(c))return false;for(let t=9;t<11;t++){let s=0;for(let i=0;i<t;i++)s+=Number(c[i])*(t+1-i);if(((s*10)%11)%10!==Number(c[t]))return false}return true}
function validCNPJ(v){const c=digits(v);if(c.length!==14||/^(\d)\1+$/.test(c))return false;const calc=n=>{let s=0,p=n-7;for(let i=0;i<n;i++){s+=Number(c[i])*p--;if(p<2)p=9}const r=s%11;return r<2?0:11-r};return calc(12)===Number(c[12])&&calc(13)===Number(c[13])}
function maskDoc(v){const c=digits(v);return c.length===11?`***.${c.slice(3,6)}.***-**`:c.length===14?`**.${c.slice(2,5)}.***/****-${c.slice(12)}`:'—'}

function newProd(np){return {...np,price10:np.price,price11:np.price,stock10:null,stock11:0,initial11:0,active:np.price>0}}
function migrateV5(){
 if(!DB||!Array.isArray(DB.products))DB=fresh();
 for(const np of NEW_PRODUCTS)if(!DB.products.some(p=>p.id===np.id))DB.products.push(newProd(np));
 for(const d of DEMO_USERS){const u=DB.users.find(x=>x.id===d.id);if(u&&!u.passHash){u.login=d.login;u.passHash=hashPass(d.login,d.pass)}}
 for(const u of DB.users)if(!u.login)u.login=u.id;
 DB.tabs=DB.tabs||[];DB.debts=DB.debts||[];DB.expenses=DB.expenses||[];DB.customers=DB.customers||[];
 DB.settings={...COMPANY_DEFAULT,...DB.settings};if(!DB.settings.address||DB.settings.address==='Informar antes de publicar')DB.settings.address=COMPANY_DEFAULT.address;
 if(DB.version!==5){DB.version=5;DB.customerSession=null}
 for(const k of Object.keys(cart))if(k.startsWith('p:')&&!onlineOk(item(k.slice(2))))delete cart[k];
 save();saveCart()}
