/* ---------- Cliente: cadastro e pontos ---------- */
const REWARDS=[['skol-lata',60],['gelo-3kg',200],['coca-2l',350],['cx-skol',1200]],REWARD_MIN=3000,POINT_DAYS=90;
const LEVELS=[['Bronze',0,0],['Prata',300,.05],['Ouro',1000,.10],['Diamante',3000,.20]];
let accTab='signup',custFails=0,custLock=0;
function rewardCost(id){return REWARDS.find(r=>r[0]===id)?.[1]??Infinity}
function custUser(){return DB.customers.find(c=>c.id===DB.customerSession&&c.account)||null}
function validLedger(c){const lim=Date.now()-POINT_DAYS*864e5;return (c.ledger||[]).filter(x=>x.date>=lim)}
function pointsBalance(c){return Math.max(0,validLedger(c).reduce((s,x)=>s+x.pts,0))}
function earned90(c){return validLedger(c).filter(x=>x.pts>0).reduce((s,x)=>s+x.pts,0)}
function levelOf(c){const e=earned90(c);let L=LEVELS[0];for(const l of LEVELS)if(e>=l[1])L=l;return L}
function eligibleCents(lines){return lines.filter(l=>!l.key.startsWith('r:')&&!(l.key.startsWith('p:')&&restricted(item(l.key.slice(2))))).reduce((s,l)=>s+l.price*l.q,0)}
function pointsFor(lines,c){const lv=c?levelOf(c):LEVELS[0];return Math.floor(eligibleCents(lines)/200*(1+lv[2]))}
function awardPoints(o){if(o.pointsGiven||!o.customer?.id)return;const c=DB.customers.find(x=>x.id===o.customer.id&&x.account);if(!c)return;const pts=pointsFor(o.lines,c);o.pointsGiven=pts||-1;if(pts>0)c.ledger.push({date:Date.now(),pts,type:'Compra '+o.code})}
function cartRewardPts(){return Object.entries(cart).filter(([k,q])=>k.startsWith('r:')&&q>0).reduce((s,[k,q])=>s+rewardCost(k.slice(2))*q,0)}
function accountPageBase(){const c=custUser();
 if(!c)return `<div class="page"><div class="narrow"><div class="page-title"><h1>👤 Minha conta</h1><p>Cadastre-se para pedir mais rápido e ver suas cartelas do Bingo de Sexta.</p></div><div class="seg">${['signup','login'].map(t=>`<button data-action="acc-tab" data-value="${t}" class="${accTab===t?'active':''}">${t==='signup'?'Criar cadastro':'Entrar'}</button>`).join('')}</div><section class="panel" style="margin-top:12px">${accTab==='login'?`<form id="custLoginForm" class="stack"><label class="field">WhatsApp<input name="phone" required inputmode="tel" autocomplete="tel" placeholder="(65) 99999-9999"></label><label class="field">Senha<input name="pass" type="password" required autocomplete="current-password"></label><button class="button block" type="submit">Entrar</button></form>`:`<form id="custSignupForm" class="stack"><label class="field">Nome completo ou razão social<input name="name" required autocomplete="name"></label><div class="grid2"><label class="field">CPF ou CNPJ<input name="doc" required inputmode="numeric" placeholder="Somente números"></label><label class="field">Data de nascimento<input name="birth" type="date" required max="${diaCuiaba()}"><small>Se for CNPJ, a do responsável</small></label></div><label class="field">WhatsApp (será o seu login)<input name="phone" required inputmode="tel" autocomplete="tel" placeholder="(65) 99999-9999"></label><label class="field">Rua / avenida<input name="street" required autocomplete="address-line1"></label><div class="grid2"><label class="field">Número<input name="number" required></label><label class="field">Bairro<input name="neighborhood" required></label></div><label class="field">Referência (opcional)<input name="reference"></label><label class="field">Código de quem te indicou (opcional)<input name="ref" value="${esc(pendingRef||'')}" placeholder="Ex.: K10-12" autocapitalize="characters"><small>Quem te indicou ganha 1 cartela do bingo</small></label><div class="grid2"><label class="field">Senha (mín. 6)<input name="pass" type="password" minlength="6" required autocomplete="new-password"></label><label class="field">Repita a senha<input name="pass2" type="password" minlength="6" required autocomplete="new-password"></label></div><label class="check"><input type="checkbox" name="lgpd" required><span>Autorizo o uso dos meus dados para entregas, conferência de idade e o Programa K10, conforme a <button type="button" class="link-btn" data-action="terms">Política de Privacidade</button>.</span></label><button class="button red block" type="submit">Criar meu cadastro</button></form>`}</section>${pointsRulesHtml()}</div></div>`;
 const bal=pointsBalance(c),lv=levelOf(c),e90=earned90(c),next=LEVELS[LEVELS.indexOf(lv)+1],pct=next?Math.min(100,Math.round((e90-lv[1])/(next[1]-lv[1])*100)):100,orders=DB.orders.filter(o=>o.customer?.id===c.id);
 return `<div class="page"><div class="acc-hero"><div><span class="eyebrow">Programa K10 · ${esc(lv[0])}</span><h1>Olá, ${esc(c.name.split(' ')[0])}!</h1><p class="tiny" style="color:#ddd;margin-top:6px">${lv[2]?`Bônus de +${Math.round(lv[2]*100)}% nos pontos · `:''}${esc(maskDoc(c.doc))} · cliente nº ${c.code||'—'}</p></div><div class="acc-pts"><strong>${bal}</strong><small>pontos válidos</small></div></div>
 <section class="panel"><div class="summary"><span>${next?`Faltam <b>${next[1]-e90}</b> pontos (em 90 dias) para o nível <b>${next[0]}</b>`:'Você está no nível máximo 💎'}</span><b>${e90} pts em 90 dias</b></div><div class="level-bar"><i style="width:${pct}%"></i></div><p class="tiny muted">Níveis: ${LEVELS.map(l=>`${l[0]} ${l[1]}+`).join(' · ')}</p></section>
 <h3 class="dashboard-sub">🎁 Troque seus pontos</h3><div class="reward-grid">${REWARDS.map(([id,pts])=>{const p=item(id);if(!p)return '';const inCart=cart['r:'+id];return `<article class="reward"><div class="ph">${productPhoto(id)}</div><b>${esc(p.name)}</b><strong>${pts} pontos</strong>${button(inCart?'✓ No carrinho':bal-cartRewardPts()>=pts?'Resgatar':'Pontos insuficientes','redeem','button small'+(inCart?' dark':''),`data-id="${id}" ${inCart||bal-cartRewardPts()<pts?'disabled':''}`)}</article>`}).join('')}</div>
 ${pointsRulesHtml()}
 <div class="grid2" style="margin-top:14px"><section class="panel"><h3>🧾 Meus pedidos</h3>${orders.length?orders.slice(0,8).map(o=>`<div class="summary"><span>${esc(o.code)} · ${esc(o.created)}<br><small class="muted">${statusLabel(o.status)}</small></span><b>${money(o.total+o.fee)}</b></div>`).join('')+button('Acompanhar pedidos','tracking','button small dark'):'<p class="muted tiny">Nenhum pedido ainda.</p>'}</section><section class="panel"><h3>📒 Extrato de pontos</h3>${(c.ledger||[]).slice().reverse().slice(0,10).map(x=>`<div class="summary"><span>${esc(x.type)}<br><small class="muted">${new Date(x.date).toLocaleDateString('pt-BR')}${x.date<Date.now()-POINT_DAYS*864e5?' · vencido':''}</small></span><b class="${x.pts<0?'red-text':'green-text'}">${x.pts>0?'+':''}${x.pts}</b></div>`).join('')||'<p class="muted tiny">Sem movimentos.</p>'}</section></div>
 <div class="form-actions" style="margin-top:16px">${button('Sair da conta','cust-logout','button dark')}${button('Excluir minha conta','cust-delete','button small outline')}</div></div>`}
function pointsRulesHtml(){return `<section class="panel" style="margin-top:14px"><h3>⭐ Como funciona o Programa K10</h3><ul class="rules"><li><b>1 ponto a cada R$ 2,00</b> em produtos de pedidos <b>entregues ou retirados</b>. Frete e tabacaria não contam.</li><li>Os pontos <b>valem 90 dias</b>.</li><li>Para trocar pontos, o pedido precisa ter pelo menos <b>${money(REWARD_MIN)} em produtos</b>.</li><li>Níveis pelos pontos ganhos em 90 dias: Prata (300) +5%, Ouro (1.000) +10%, Diamante (3.000) +20% de bônus.</li><li>Prêmios: ${REWARDS.map(([id,p])=>`${esc(item(id)?.name||id)} ${p} pts`).join(' · ')}.</li></ul></section>`}
function staffCustomers(){const rows=DB.customers;return `<div class="page-title"><h2>👥 Clientes</h2><p>Cadastros com conta (Programa K10) e clientes de pedidos. A K10 confere e aprova.</p></div><section class="panel"><div class="table-wrap"><table class="data-table"><tr><th>Cliente</th><th>Tipo</th><th>CPF/CNPJ</th><th>Contato</th><th>Endereço</th><th>Pontos</th><th>Nível</th><th>Status</th><th>Ação K10</th></tr>${rows.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.account?'<span class="pill ok">Conta</span>':'<span class="pill">Pedido</span>'}</td><td>${c.account?esc(maskDoc(c.doc)):'—'}</td><td>${esc(c.phone)}</td><td>${esc([c.street,c.number,c.neighborhood].filter(Boolean).join(', '))}</td><td>${c.account?pointsBalance(c):'—'}</td><td>${c.account?levelOf(c)[0]:'—'}</td><td><span class="pill ${c.status==='aprovado'?'ok':'warning'}">${esc(c.status)}</span></td><td>${c.status!=='aprovado'?button('Aprovar','approve-customer','mini-btn',`data-id="${esc(c.id)}"`):'✓'}</td></tr>`).join('')||'<tr><td colspan="9" class="muted">Nenhum cliente ainda.</td></tr>'}</table></div></section>`}

