/* ---------- Sabores (Ice Cabaré e outros) ---------- */
function flavorModal(pid,target){const p=item(pid);const cur=target==='tab'?(curTab()?.flav?.[pid]||{}):(cart['p:'+pid]?(cartFlav[pid]||{}):{});flavDraft={pid,target,dist:{...cur}};drawFlavor()}
function drawFlavor(){const {pid,target,dist}=flavDraft,p=item(pid),tot=Object.values(dist).reduce((a,b)=>a+b,0),pr=target==='tab'?p.price11:p.price10;
 popup('🍹 '+p.name+' · escolha os sabores',`<p class="page-summary" style="margin-top:0">Escolha um sabor ou monte <b>misto</b>: use + e − em cada um.</p><div class="flav-grid">${FLAVORS[pid].map(([f,im])=>`<div class="flav ${dist[f]?'on':''}"><img src="${img(im)}" alt="${esc(f)}"><b>${esc(f)}</b><div class="quantity"><button type="button" data-action="flav-step" data-value="${esc(f)}" data-delta="-1" aria-label="Menos ${esc(f)}">−</button><b>${dist[f]||0}</b><button type="button" data-action="flav-step" data-value="${esc(f)}" data-delta="1" aria-label="Mais ${esc(f)}">+</button></div></div>`).join('')}</div><div class="form-actions" style="margin:12px 0">${button('🎨 Misto: 1 de cada','flav-mix','button small dark')}${button('Limpar','flav-clear','button small outline')}</div><div class="summary total"><span>${tot} unidade(s)</span><b>${money(pr*tot)}</b></div>${button(tot?'✓ Confirmar sabores':'Remover do pedido','flav-ok','button red block')}`)}
function applyFlavor(){const {pid,target,dist}=flavDraft,p=item(pid);for(const k of Object.keys(dist))if(!dist[k])delete dist[k];const tot=Object.values(dist).reduce((a,b)=>a+b,0);
 if(target==='tab'){const t=curTab()||newTab('Balcão');const before=t.items[pid]||0;if(tot>before&&!available(p,'k11',reservedK11(pid)-before+tot))throw Error('Estoque K11 insuficiente: '+p.name);if(tot)t.items[pid]=tot;else delete t.items[pid];t.flav=t.flav||{};t.flav[pid]=dist;t.log.push({at:now(),by:user()?.name,id:pid,flav:flavText(dist)});save()}
 else{if(tot&&!onlineOk(p))throw Error('Produto indisponível.');if(tot&&!available(p,'k10',tot))throw Error('Estoque insuficiente: '+p.name);if(tot)cart['p:'+pid]=tot;else delete cart['p:'+pid];cartFlav[pid]=dist;saveCart();saveFlav()}
 flavDraft=null;closeModal();render();toast(tot?`${p.name}: ${flavText(dist)}`:'Removido.')}
function lineName(key){if(key.startsWith('r:'))return '🎁 Prêmio: '+(item(key.slice(2))?.name||'Produto');if(key.startsWith('c:'))return combo(key.slice(2))?.name||'Combo';const id=key.replace(/^p:/,''),n=item(id)?.name||'Produto',f=FLAVORS[id]?flavText(cartFlav[id]):'';return f?`${n} (${f})`:n}

