function lastOrderStatus(){const cu=custUser();const os=DB.orders.filter(o=>o.origin==='site'&&(!cu||o.customer?.id===cu.id));const o=os[0];if(!o)return ['Nenhum pedido',''];const s=o.status;if(s==='em_rota')return ['Rota de entrega','go'];if(['pendente','aprovado','separando','pronto'].includes(s))return ['Em andamento','wait'];if(s==='cancelado')return ['Cancelado','bad'];return ['Entregue','ok']}
