/* ---------- Formulários: não perder o que já foi digitado ---------- */
function rememberField(e){const el=e.target,f=el.form;if(!f||!f.id||!el.name||el.type==='password'||el.type==='file'||el.type==='hidden')return;(drafts[f.id]=drafts[f.id]||{})[el.name]=el.type==='checkbox'?el.checked:el.value}
function restoreDrafts(){for(const [fid,vals] of Object.entries(drafts)){const f=document.getElementById(fid);if(!f)continue;for(const [n,v] of Object.entries(vals)){const el=f.elements[n];if(!el||!el.type||el.type==='password')continue;if(el.type==='checkbox')el.checked=!!v;else el.value=v}}}

/* ---------- Motorista: ganhos, lucro e horários ---------- */
const DAY=864e5,WD=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
function parseBR(s){const m=/(\d{2})\/(\d{2})\/(\d{4}),?\s+(\d{2}):(\d{2})/.exec(s||'');return m?new Date(+m[3],m[2]-1,+m[1],+m[4],+m[5]).getTime():null}
function deliveredTs(o){return o.deliveredAt||parseBR(o.created)||Date.now()}
function startDay(t){const d=new Date(t);d.setHours(0,0,0,0);return d.getTime()}
function weekStartTs(t=Date.now()){const d=new Date(startDay(t));return d.getTime()-((d.getDay()+6)%7)*DAY}
function monthStartTs(t=Date.now()){const d=new Date(t);return new Date(d.getFullYear(),d.getMonth(),1).getTime()}
function payFor(n){const s=DB.settings;return n*s.driverFee+Math.floor(n/s.driverBonusEvery)*s.driverBonus}
function driverStats(uid,from,to){const os=DB.orders.filter(o=>o.driverId===uid&&o.status==='entregue').filter(o=>{const t=deliveredTs(o);return t>=from&&t<to});const u=DB.users.find(x=>x.id===uid),n=os.length,gain=payFor(n),cost=n*(u?.costPerDelivery??200);return{os,n,gain,cost,profit:gain-cost,km:n}}
function barChart(bars,fmt,label){const max=Math.max(1,...bars.map(b=>b.v));return `<div class="vbars" role="img" aria-label="${esc(label)}">${bars.map(b=>`<div class="vbar ${b.hi?'hi':''}" tabindex="0" data-tip="${esc(b.l)}: ${esc(fmt(b.v))}"><i style="height:${b.v?Math.max(3,b.v/max*100):0}%"></i><span>${esc(b.s)}</span></div>`).join('')}</div>`}
function driverEarnings(){const u=user(),now0=Date.now(),s=DB.settings;const isW=drvPeriod==='week';const from=isW?weekStartTs():monthStartTs(),to=now0+1,prevFrom=isW?from-7*DAY:monthStartTs(from-DAY),prevTo=from;
 const cur=driverStats(u.id,from,to),prev=driverStats(u.id,prevFrom,prevTo),today=driverStats(u.id,startDay(now0),to);
 const diff=prev.profit?((cur.profit-prev.profit)/Math.abs(prev.profit)):null,next=s.driverBonusEvery-(today.n%s.driverBonusEvery);
 const days=isW?7:new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate();const bars=[];for(let i=0;i<days;i++){const d0=from+i*DAY,st=driverStats(u.id,d0,d0+DAY);const dd=new Date(d0);bars.push({v:st.gain,l:(isW?WD[dd.getDay()]+' ':'')+dd.toLocaleDateString('pt-BR'),s:isW?WD[dd.getDay()]:(i%5===0||i===days-1?String(i+1):''),hi:startDay(now0)===d0})}
 const all=DB.orders.filter(o=>o.delivery==='entrega'&&o.status!=='cancelado'),hours=Array(24).fill(0),wds=Array(7).fill(0);for(const o of all){const t=parseBR(o.created);if(!t)continue;const d=new Date(t);hours[d.getHours()]++;wds[d.getDay()]++}
 const top=hours.map((v,h)=>[h,v]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,3),topD=wds.map((v,d)=>[d,v]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,2),hrs=[];for(let h=9;h<=27;h++){const hh=h%24;hrs.push({v:hours[hh],l:String(hh).padStart(2,'0')+'h',s:h%3===0?String(hh):'',hi:top.some(t=>t[0]===hh)})}
 const goal=u.weeklyGoal||0,wk=driverStats(u.id,weekStartTs(),to),gp=goal?Math.min(100,Math.round(wk.profit/goal*100)):0;
 return `<div class="page-title"><h2>💰 Meus ganhos</h2><p>Valor por entrega ${money(s.driverFee)} + bônus de ${money(s.driverBonus)} a cada ${s.driverBonusEvery} entregas. Lucro = ganhos − seu custo por entrega.</p></div>
 <div class="seg" style="max-width:320px">${[['week','Esta semana'],['month','Este mês']].map(([k,t])=>`<button data-action="drv-period" data-value="${k}" class="${drvPeriod===k?'active':''}">${t}</button>`).join('')}</div>
 <div class="kpi-grid">${kpi('Entregas',String(cur.n),isW?'nesta semana':'neste mês')}${kpi('Ganhos',money(cur.gain),'com bônus')}${kpi('Custos',money(cur.cost),money(u.costPerDelivery??200)+' por entrega')}${kpi('Lucro',`<em style="font-style:normal" class="${cur.profit<0?'red-text':'green-text'}">${money(cur.profit)}</em>`,diff===null?'sem período anterior para comparar':`${diff>=0?'▲':'▼'} ${Math.abs(diff*100).toFixed(0)}% vs ${isW?'semana':'mês'} passado`)}</div>
 <div class="two-column"><section class="panel"><h3>📈 Ganhos por dia</h3><p class="tiny muted" style="margin-bottom:8px">Toque numa barra para ver o valor. Hoje em destaque.</p>${barChart(bars,money,'Ganhos por dia')}</section>
 <section class="panel stack"><h3>🎯 Hoje e metas</h3><div class="summary"><span>Entregas hoje</span><b>${today.n} · ${money(today.gain)}</b></div><div class="drv-bonus"><b>Faltam ${next} entrega(s)</b> para o próximo bônus de ${money(s.driverBonus)}<div class="level-bar"><i style="width:${((s.driverBonusEvery-next)/s.driverBonusEvery)*100}%"></i></div></div>${goal?`<div><div class="summary"><span>Meta de lucro da semana</span><b>${money(wk.profit)} / ${money(goal)}</b></div><div class="level-bar"><i style="width:${gp}%"></i></div><p class="tiny muted">${gp>=100?'Meta batida! 🏆':'Faltam '+money(goal-wk.profit)}</p></div>`:''}<form id="driverCostForm" class="grid2"><label class="field">Meu custo por entrega (R$)<input name="cost" inputmode="decimal" value="${((u.costPerDelivery??200)/100).toFixed(2).replace('.',',')}"><small>combustível, desgaste, celular</small></label><label class="field">Meta de lucro semanal (R$)<input name="goal" inputmode="decimal" value="${goal?(goal/100).toFixed(2).replace('.',','):''}" placeholder="Ex.: 500,00"></label><button class="button small" type="submit" style="grid-column:1/-1">Salvar</button></form></section></div>
 <section class="panel" style="margin-top:14px"><h3>⏰ Horários com mais pedidos</h3>${all.length>=5?`<p class="page-summary" style="margin-top:0">💡 Fique disponível ${top.map(([h])=>`<b>${String(h).padStart(2,'0')}h–${String((h+1)%24).padStart(2,'0')}h</b>`).join(', ')}${topD.length?` · dias mais fortes: <b>${topD.map(([d])=>WD[d]).join(' e ')}</b>`:''}.</p>`:`<p class="page-summary" style="margin-top:0">Ainda há poucos pedidos para calcular os horários de pico (${all.length} até agora). A dica fica mais precisa a cada entrega.</p>`}${barChart(hrs,v=>v+' pedido(s)','Pedidos por hora')}<p class="tiny muted" style="margin-top:6px">Pedidos de entrega por hora (9h às 3h), de todos os motoristas. As barras destacadas são os 3 horários mais fortes.</p></section>
 <section class="panel" style="margin-top:14px"><h3>🧾 Últimas entregas</h3>${cur.os.length?cur.os.slice(0,10).map(o=>`<div class="summary"><span>${esc(o.code)} · ${esc(o.customer?.neighborhood||'')}<br><small class="muted">${new Date(deliveredTs(o)).toLocaleString('pt-BR')}</small></span><b>${money(s.driverFee)}</b></div>`).join(''):'<p class="muted tiny">Nenhuma entrega concluída neste período.</p>'}</section>`}

/* ---------- Ações e eventos v6 ---------- */
async function newAction2(el){const a=el.dataset.action,v=el.dataset.value;
 switch(a){
 case 'flav-step':{if(!flavDraft)return true;const d=flavDraft.dist;d[v]=Math.max(0,(d[v]||0)+Number(el.dataset.delta));drawFlavor();return true}
 case 'flav-mix':if(!flavDraft)return true;for(const [f] of FLAVORS[flavDraft.pid])flavDraft.dist[f]=(flavDraft.dist[f]||0)+1;drawFlavor();return true;
 case 'flav-clear':if(flavDraft){flavDraft.dist={};drawFlavor()}return true;
 case 'flav-ok':if(flavDraft)applyFlavor();return true;
 case 'drv-period':drvPeriod=v;render();return true;
 case 'clear-cart':cartFlav={};saveFlav();return false;
 }
 return newAction(el)}
