const BINGO_FORMS=['bingoCardForm','bingoSettingsForm','bingoDeleteForm','bingoRoundForm'];
const BALL_L=n=>'BINGO'[Math.min(4,Math.floor((n-1)/15))];
const ROUND_SEED=[
 {time:'19:00',label:'1ª rodada',mode:'linha',items:[['cx-heineken',2],['coca-2l',2],['monster',2],['gelo-3kg',1],['coca-1l',1]]},
 {time:'21:00',label:'2ª rodada',mode:'linha',items:[['kislla-red-fruits',1],['kislla-tradicional',1],['cx-skol',1],['cx-itaipava',1],['gelo-3kg',1],['redbull',1],['coca-lata',1]]},
 {time:'23:00',label:'3ª rodada',mode:'linha',items:[['red-label',1],['cx-heineken',1],['gelo-3kg',1]]},
 {time:'00:00',label:'Rodada final · meia-noite',mode:'cheia',items:[['buchanans',1],['old-parr',1],['cx-heineken',2],['vulcano',1]]}];
const WEEK_DRAWS=[['Segunda'],['Terça'],['Quarta'],['Quinta']];
let bingoTimer=null,bingoAuto=false,bingoControls=true,bingoQuery='',lastCards=[];
function ymd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function nextFriday(){const d=new Date();d.setHours(12,0,0,0);const add=(5-d.getDay()+7)%7;d.setDate(d.getDate()+add);return ymd(d)}
function newEvent(date){return{id:uid(),date,title:'Bingo de Sexta K11',created:now(),rounds:ROUND_SEED.map((r,i)=>({id:'r'+(i+1),...JSON.parse(JSON.stringify(r)),status:'aguardando',drawn:[],winners:[],startedAt:null,endedAt:null}))}}
function migrateV7(){const b=DB.bingo=DB.bingo||{};b.events=b.events||[];b.cards=b.cards||[];b.log=b.log||[];b.seqCard=b.seqCard||0;b.maxPerClient=b.maxPerClient||3;
 if(!b.events.length){const e=newEvent(nextFriday());b.events.push(e);b.currentId=e.id}if(!b.events.some(e=>e.id===b.currentId))b.currentId=b.events[b.events.length-1].id;
 if(!b.live)b.live={roundIdx:0};ensureCodes();save()}
function ensureCodes(){let mx=DB.customers.reduce((m,c)=>Math.max(m,c.code||0),0);for(const c of DB.customers)if(!c.code)c.code=++mx;DB.custSeq=mx}
function bEvent(){return DB.bingo.events.find(e=>e.id===DB.bingo.currentId)}
function bRound(){const e=bEvent();return e.rounds[Math.min(DB.bingo.live.roundIdx,e.rounds.length-1)]}
function roundValue(r){return r.items.reduce((s,[id,q])=>s+(item(id)?.price10||0)*q,0)}
function eventValue(e){return e.rounds.reduce((s,r)=>s+roundValue(r),0)}
function roundDate(e,r){const d=new Date(e.date+'T'+r.time+':00');if(r.time==='00:00')d.setDate(d.getDate()+1);return d}
function fmtDay(s){const d=new Date(s+'T12:00:00');return WD[d.getDay()]+' '+d.toLocaleDateString('pt-BR').slice(0,5)}
function hourLabel(t){return t==='00:00'?'00h · meia-noite':t.replace(':00','h')}
function activeCards(eid=DB.bingo.currentId){return DB.bingo.cards.filter(c=>c.eventId===eid&&!c.deleted)}
function blog(action,details){DB.bingo.log.unshift({at:now(),by:user()?.name||'—',action,details});DB.bingo.log=DB.bingo.log.slice(0,300)}
function rnd(n){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]%n}
function pick(from,to,k){const pool=[];for(let i=from;i<=to;i++)pool.push(i);const out=[];while(out.length<k)out.push(pool.splice(rnd(pool.length),1)[0]);return out.sort((a,b)=>a-b)}
function makeNumbers(){const cols=[0,1,2,3,4].map(c=>pick(c*15+1,c*15+15,5));cols[2][2]=0;const g=[];for(let r=0;r<5;r++)for(let c=0;c<5;c++)g.push(cols[c][r]);return g}
function cardKey(nums){return nums.join('-')}
function verify(c){return sha256('k10bingo|'+c.id+'|'+c.eventId+'|'+c.numbers.join(',')).slice(0,6).toUpperCase()}
function marks(c,drawn){const s=new Set(drawn);return c.numbers.map(n=>n===0||s.has(n))}
function wins(c,drawn,mode){const m=marks(c,drawn);if(mode==='cheia')return m.every(Boolean);const L=[];for(let i=0;i<5;i++){L.push([0,1,2,3,4].map(j=>i*5+j));L.push([0,1,2,3,4].map(j=>j*5+i))}L.push([0,6,12,18,24],[4,8,12,16,20]);return L.some(l=>l.every(k=>m[k]))}
function cardGrid(c,drawn=[],big=false){const m=marks(c,drawn);return `<div class="bcard ${big?'big':''}"><div class="bhead">${[...'BINGO'].map(l=>`<b>${l}</b>`).join('')}</div><div class="bgrid">${c.numbers.map((n,i)=>`<span class="${n===0?'free':m[i]?'hit':''}">${n===0?'★':n}</span>`).join('')}</div></div>`}
function cardText(c){const e=DB.bingo.events.find(x=>x.id===c.eventId),rows=[];for(let r=0;r<5;r++)rows.push(c.numbers.slice(r*5,r*5+5).map(n=>n===0?' ★':String(n).padStart(2,'0')).join('  '));return `🎱 *BINGO K11 · ${fmtDay(e.date)}*\nCartela nº *${c.code}* · ${c.clientName} (cliente nº ${c.clientCode})\n\n B    I    N    G    O\n${rows.join('\n')}\n\nVerificação: ${verify(c)}\nSorteios: ${e.rounds.map(r=>hourLabel(r.time)).join(' · ')}\nPrêmios em mercadorias · cartela gratuita · proibido para menores de 18 anos.`}
function waLink(phone,text){const d=digits(phone);const n=d.length>=10&&d.length<=11?'55'+d:d;return `https://wa.me/${n}?text=${encodeURIComponent(text)}`}
function prizeStrip(r,max=6){return `<div class="prize-strip">${r.items.slice(0,max).map(([id,q])=>`<figure>${productPhoto(id)}<figcaption>${q>1?q+'× ':''}${esc(item(id)?.name||id)}</figcaption></figure>`).join('')}</div>`}
function nextRound(e){const t=Date.now();return e.rounds.find(r=>r.status!=='encerrada'&&roundDate(e,r).getTime()+60*60e3>t)||null}

