function bingoBanner(){const e=bEvent();return `<section class="bingo-banner" data-action="bingo" role="button" tabindex="0"><div class="bb-balls"><i>B</i><i>7</i><i>N</i><i>42</i><i>O</i></div><div class="bb-txt"><span class="eyebrow">🎱 BINGO DE SEXTA K11 · CARTELA GRÁTIS</span><h2>${money(eventValue(e))} <em>em prêmios</em></h2><p>${fmtDay(e.date)} · ${e.rounds.map(r=>hourLabel(r.time).replace(' · meia-noite','')).join(' · ')} · peça sua cartela ao atendente</p></div><span class="button">Ver prêmios →</span></section>`}
