var comboEditId=null,comboAddPick='';
var pendingRef=(()=>{let r=null;try{r=new URLSearchParams(location.search).get('ref')||(location.hash.match(/ref=([\w-]+)/)||[])[1]||null}catch{}try{if(r)sessionStorage.setItem('k10-ref',r);else r=sessionStorage.getItem('k10-ref')}catch{}return r})();
(function(){if(!DB.bingo.autoSec)DB.bingo.autoSec=8;save()})();

/* ---------- Cartela genérica (pedido, indicação) ---------- */
function giveCard(c,origin,note){ensureCodes();const e=targetEvent(),used=new Set(activeCards(e.id).map(x=>cardKey(x.numbers)));let nums;do nums=makeNumbers();while(used.has(cardKey(nums)));const card={id:uid(),code:String(++DB.bingo.seqCard).padStart(4,'0'),eventId:e.id,numbers:nums,customerId:c.account?c.id:null,clientCode:c.code,clientName:c.name,phone:c.phone||'',createdBy:note,createdById:null,origin,created:now()};DB.bingo.cards.push(card);blog('cartela por '+origin,card.code+' · '+c.name+' nº '+c.code+' · '+note);return card}

/* ---------- Indique e ganhe ---------- */
function refCodeOf(c){return 'K10-'+c.code}
function refLink(c){let base='';try{base=location.href.split('#')[0].split('?')[0]}catch{}return base+'?ref='+refCodeOf(c)}
function grantReferral(newC,raw){const code=Number(String(raw||'').trim().toUpperCase().replace(/^K10\s*-?\s*/,'').replace(/\D/g,''));if(!code)return null;const ref=DB.customers.find(x=>x.code===code&&x.account&&x.id!==newC.id);if(!ref){return null}if(newC.referredBy)return null;if(digits(ref.phone)===digits(newC.phone)||(ref.doc&&ref.doc===newC.doc))return null;newC.referredBy=ref.code;ref.referrals=ref.referrals||[];ref.referrals.push({code:newC.code,name:firstName(newC.name),at:now()});const card=giveCard(ref,'indicacao','Indicou '+firstName(newC.name)+' (nº '+newC.code+')');try{sessionStorage.removeItem('k10-ref')}catch{}pendingRef=null;return card}
function referralBox(c){const n=(c.referrals||[]).length,link=refLink(c),msg=`Peça sua bebida gelada na K10 Delivery! 🍻 Faça seu cadastro pelo meu link: ${link} (ou use meu código ${refCodeOf(c)}).`;return `<section class="panel ref-box"><div><h3 style="margin:0">🎁 Indique e ganhe cartelas</h3><p class="tiny" style="margin-top:6px;color:#e2e1e6">Cada amigo que se cadastrar pelo seu link (ou com o seu código) dá <b>1 cartela grátis</b> do Bingo de Sexta para você.</p></div><div class="ref-code"><small>Seu código</small><b>${refCodeOf(c)}</b></div><input class="input" readonly value="${esc(link)}" data-selectall="1"><div class="form-actions">${button('📋 Copiar link','ref-copy','button small',`data-value="${esc(link)}"`)}<a class="button small dark" href="https://wa.me/?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener">💬 Enviar no WhatsApp</a></div><p class="tiny muted">${n?`Você já indicou <b>${n}</b> amigo(s): ${(c.referrals||[]).slice(-5).map(r=>esc(r.name)).join(', ')}.`:'Você ainda não indicou ninguém.'}</p></section>`}

/* ---------- Combos: criar e editar ---------- */
function comboRetail(c){return c.items.reduce((s,[id,q])=>s+(item(id)?.price10||0)*q,0)}
function staffCombos(){const ed=DB.combos.find(c=>c.id===comboEditId);return `<div class="page-title"><h2>🎁 Combos K10</h2><p>Crie, edite, pause ou exclua combos. O preço do combo é independente do preço dos produtos.</p></div><div class="form-actions" style="margin-bottom:12px">${button('＋ Novo combo','combo-new','button')}</div>${ed?comboEditor(ed):''}
 <div class="grid2">${DB.combos.map(c=>{const old=comboRetail(c),cost=comboCost(c),disc=old?Math.round((1-c.price/old)*100):0;return `<section class="panel combo-adm ${c.enabled?'':'off'}"><div class="combo-thumbs">${c.items.slice(0,4).map(([id])=>productPhoto(id)).join('')||'<span class="tiny muted">Sem produtos</span>'}</div><div class="staff-header"><div><h3 style="margin:0">${esc(c.name)}</h3><p class="tiny muted">${esc(c.description)}</p></div><span class="pill ${c.enabled?'ok':'bad'}">${c.enabled?'Ativo':'Pausado'}</span></div><div class="summary"><span>Preço do combo</span><b>${money(c.price)}</b></div><div class="summary"><span>Separado sairia</span><b>${money(old)}${disc>0?` · <span class="green-text">-${disc}%</span>`:''}</b></div><div class="summary"><span>Custo · margem</span><b>${cost===null?'faltam custos':money(cost)+' · '+(c.price?Math.round((c.price-cost)/c.price*100):0)+'%'}</b></div><div class="form-actions">${button('✏️ Editar','combo-edit','button small',`data-id="${esc(c.id)}"`)}${button(c.enabled?'Pausar':'Ativar','toggle-combo','button small dark',`data-id="${esc(c.id)}"`)}${button('Excluir','combo-del','button small outline',`data-id="${esc(c.id)}"`)}</div></section>`}).join('')}</div>`}
function comboEditor(c){const old=comboRetail(c),cost=comboCost(c),prodOpts=DB.products.filter(p=>p.active&&!restricted(p)).map(p=>`<option value="${p.id}" ${comboAddPick===p.id?'selected':''}>${esc(p.name)} · ${money(p.price10)}</option>`).join('');
 return `<section class="panel combo-editor"><div class="staff-header"><h3 style="margin:0">✏️ Editando: ${esc(c.name)}</h3>${button('✓ Concluir','combo-done','button small')}</div>
 <div class="grid2"><label class="field">Nome do combo<input data-cedit="name" value="${esc(c.name)}" maxlength="40"></label><label class="field">Preço do combo (R$)<input data-cedit="price" inputmode="decimal" value="${(c.price/100).toFixed(2).replace('.',',')}"></label></div><label class="field">Descrição (aparece no site)<input data-cedit="description" value="${esc(c.description)}" maxlength="90"></label>
 <div class="opt-items">${c.items.map(([id,q],i)=>`<div class="tab-line">${productPhoto(id)}<div class="nm"><b>${esc(item(id)?.name||id)}</b><small>${money((item(id)?.price10||0)*q)}</small></div><div class="quantity"><button data-action="citem-q" data-i="${i}" data-delta="-1" aria-label="Diminuir quantidade">−</button><b>${q}</b><button data-action="citem-q" data-i="${i}" data-delta="1" aria-label="Aumentar quantidade">+</button></div></div>`).join('')||'<p class="tiny muted">Adicione os produtos do combo.</p>'}</div>
 <div class="add-item"><select data-cpick="1">${prodOpts}</select>${button('＋ Produto','citem-add','button small')}</div>
 <div class="summary"><span>Separado sairia</span><b>${money(old)}</b></div><div class="summary"><span>Desconto do combo</span><b>${old?Math.round((1-c.price/old)*100):0}%</b></div><div class="summary"><span>Custo · lucro</span><b>${cost===null?'faltam custos':money(cost)+' · '+money(c.price-cost)}</b></div>${cost!==null&&c.price<cost?notice('⚠️ O preço está abaixo do custo: este combo dá prejuízo.','red'):''}</section>`}

/* ---------- Entrega x Retirada ---------- */
function channelStats(ym){const os=DB.orders.filter(o=>['entregue','retirado'].includes(o.status)&&inMonth(o,ym));const ch={entrega:[],retirada:[]};for(const o of os)(o.delivery==='entrega'?ch.entrega:ch.retirada).push(o);
 const calc=list=>{let rev=0,fees=0,cost=0;for(const o of list){rev+=o.total;fees+=o.fee;cost+=orderCostInfo(o).cost}return{n:list.length,rev,fees,cost,gross:rev-cost,ticket:list.length?Math.round((rev+fees)/list.length):0}};
 const E=calc(ch.entrega),R=calc(ch.retirada);const byDriver={};for(const o of ch.entrega)if(o.driverId)byDriver[o.driverId]=(byDriver[o.driverId]||0)+1;E.driverPay=Object.values(byDriver).reduce((s,n)=>s+payFor(n),0)+ch.entrega.filter(o=>!o.driverId).length*DB.settings.driverFee;E.deliveryResult=E.fees-E.driverPay;E.total=E.gross+E.deliveryResult;R.driverPay=0;R.deliveryResult=0;R.total=R.gross;return{E,R}}
function deliveryPanel(){const {E,R}=channelStats(expMonth),tot=E.n+R.n,share=tot?Math.round(E.n/tot*100):0,row=(n,f)=>`<tr><td>${n}</td><td>${f(E)}</td><td>${f(R)}</td></tr>`;
 return `<section class="panel" style="margin-top:14px"><h3>🛵 Entrega x 🏪 Retirada · ${monthLabel(expMonth)}</h3><div class="split-bar" title="Entregas ${share}%"><i style="width:${share}%"></i><span>🛵 Entrega ${share}%</span><span>🏪 Retirada ${100-share}%</span></div><div class="table-wrap" style="margin-top:10px"><table class="data-table"><tr><th>Indicador</th><th>🛵 Entrega</th><th>🏪 Retirada / balcão</th></tr>${row('Pedidos concluídos',s=>s.n)}${row('Faturamento (produtos)',s=>money(s.rev))}${row('Lucro bruto dos produtos',s=>money(s.gross))}${row('(+) Taxas de entrega cobradas',s=>money(s.fees))}${row('(−) Pagamento dos motoristas',s=>money(s.driverPay))}${row('= Resultado da entrega',s=>`<b class="${s.deliveryResult<0?'red-text':'green-text'}">${money(s.deliveryResult)}</b>`)}${row('Lucro total do canal',s=>`<b>${money(s.total)}</b>`)}${row('Ticket médio (com taxa)',s=>money(s.ticket))}</table></div><p class="tiny muted" style="margin-top:8px">Pagamento dos motoristas pela regra da aba Equipe: ${money(DB.settings.driverFee)} por entrega + ${money(DB.settings.driverBonus)} a cada ${DB.settings.driverBonusEvery}. Se o resultado da entrega ficar negativo, a taxa cobrada não paga o motorista.</p></section>`}
