async function newAction6(el){const a=el.dataset.action,id=el.dataset.id,d=el.dataset;
 switch(a){
 case 'ref-copy':try{await navigator.clipboard.writeText(d.value);toast('Link copiado! Mande para os amigos.')}catch{toast('Toque no link acima e copie.',true)}return true;
 case 'combo-new':{if(!admin())throw Error('Somente CEO.');const c={id:'combo-'+uid().slice(0,8),name:'Novo combo',description:'Monte os itens abaixo',items:[],price:0,enabled:false};DB.combos.unshift(c);comboEditId=c.id;save();render();toast('Combo criado pausado. Monte os itens e ative quando estiver pronto.');return true}
 case 'combo-edit':case 'edit-combo':if(!admin())throw Error('Somente CEO.');comboEditId=id;render();setTimeout(()=>$('.combo-editor')?.scrollIntoView({behavior:'smooth'}),50);return true;
 case 'combo-done':comboEditId=null;render();toast('Combo salvo.');return true;
 case 'citem-add':{if(!admin())throw Error('Somente CEO.');const c=DB.combos.find(x=>x.id===comboEditId);const sel=el.parentElement.querySelector('[data-cpick]')?.value;if(!c||!sel)return true;comboAddPick=sel;const it=c.items.find(x=>x[0]===sel);if(it)it[1]++;else c.items.push([sel,1]);if(!c.price)c.price=comboRetail(c);save();render();return true}
 case 'citem-q':{const c=DB.combos.find(x=>x.id===comboEditId);if(!c)return true;const i=Number(d.i);c.items[i][1]+=Number(d.delta);if(c.items[i][1]<=0)c.items.splice(i,1);save();render();return true}
 case 'combo-del':{if(!admin())throw Error('Somente CEO.');const c=DB.combos.find(x=>x.id===id);popup('Excluir combo',`<p class="page-summary">Excluir <b>${esc(c.name)}</b>? Ele sai do site e dos carrinhos. Pedidos antigos continuam no histórico.</p><div class="form-actions">${button('Excluir','combo-del-ok','button red',`data-id="${esc(c.id)}"`)}${button('Cancelar','close','button dark')}</div>`);return true}
 case 'combo-del-ok':{DB.combos=DB.combos.filter(x=>x.id!==id);delete cart['c:'+id];saveCart();if(comboEditId===id)comboEditId=null;save();closeModal();render();toast('Combo excluído.');return true}
 case 'toggle-combo':{if(!admin())throw Error('Somente CEO.');const c=DB.combos.find(x=>x.id===id);if(!c.enabled&&(!c.items.length||!c.price))throw Error('Adicione produtos e preço antes de ativar.');c.enabled=!c.enabled;save();render();return true}
 case 'bingo-auto':{if(!canRun())throw Error('Somente equipe.');if(bingoAuto){stopAuto()}else{bingoAuto=true;drawBall();bingoTimer=setInterval(()=>{try{drawBall()}catch(err){stopAuto();toast(err.message,true)}},(DB.bingo.autoSec||8)*1000)}drawLive();return true}
 }
 return newAction5(el)}
