/* ---------- Segurança da equipe: senha + código de 6 dígitos (TOTP) ---------- */
function sha1(bytes){const l=bytes.length,nW=((l+8>>6)+1)*16,w=new Array(nW).fill(0);for(let i=0;i<l;i++)w[i>>2]|=bytes[i]<<(24-(i%4)*8);w[l>>2]|=0x80<<(24-(l%4)*8);w[nW-1]=l*8;let h0=0x67452301,h1=0xEFCDAB89,h2=0x98BADCFE,h3=0x10325476,h4=0xC3D2E1F0;const W=new Array(80);
 for(let j=0;j<nW;j+=16){for(let t=0;t<80;t++){W[t]=t<16?w[j+t]|0:(()=>{const x=W[t-3]^W[t-8]^W[t-14]^W[t-16];return (x<<1)|(x>>>31)})()}let a=h0,b=h1,c=h2,d=h3,e=h4;for(let t=0;t<80;t++){const f=t<20?(b&c)|(~b&d):t<40?b^c^d:t<60?(b&c)|(b&d)|(c&d):b^c^d,k=t<20?0x5A827999:t<40?0x6ED9EBA1:t<60?0x8F1BBCDC:0xCA62C1D6;const tmp=(((a<<5)|(a>>>27))+f+e+k+W[t])|0;e=d;d=c;c=(b<<30)|(b>>>2);b=a;a=tmp}h0=(h0+a)|0;h1=(h1+b)|0;h2=(h2+c)|0;h3=(h3+d)|0;h4=(h4+e)|0}
 const out=[];for(const h of [h0,h1,h2,h3,h4])out.push((h>>>24)&255,(h>>>16)&255,(h>>>8)&255,h&255);return out}
function hmacSha1(key,msg){if(key.length>64)key=sha1(key);const k=key.concat(new Array(64-key.length).fill(0));return sha1(k.map(b=>b^0x5c).concat(sha1(k.map(b=>b^0x36).concat(msg))))}
const B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function b32enc(bytes){let bits='',out='';for(const b of bytes)bits+=b.toString(2).padStart(8,'0');for(let i=0;i+5<=bits.length;i+=5)out+=B32[parseInt(bits.slice(i,i+5),2)];return out}
function b32dec(s){let bits='';for(const ch of s.replace(/[\s=]/g,'').toUpperCase()){const v=B32.indexOf(ch);if(v<0)continue;bits+=v.toString(2).padStart(5,'0')}const out=[];for(let i=0;i+8<=bits.length;i+=8)out.push(parseInt(bits.slice(i,i+8),2));return out}
function totp(secret,step=0,t=Date.now()){let ctr=Math.floor(t/30000)+step;const msg=[];for(let i=7;i>=0;i--){msg[i]=ctr&255;ctr=Math.floor(ctr/256)}const h=hmacSha1(b32dec(secret),msg),o=h[19]&15;const bin=((h[o]&127)<<24)|(h[o+1]<<16)|(h[o+2]<<8)|h[o+3];return String(bin%1e6).padStart(6,'0')}
function totpOk(secret,code){code=String(code||'').replace(/\D/g,'');return [-1,0,1].some(s=>totp(secret,s)===code)}
function newSecret(){const a=new Uint8Array(20);crypto.getRandomValues(a);return b32enc([...a])}
function otpUri(u,secret){return `otpauth://totp/${encodeURIComponent('K10:'+u.login)}?secret=${secret}&issuer=K10%20Delivery&digits=6&period=30`}
