let snowVid=null,snowRAF=0,snowVis=new Set(),snowIO=null,snowLast=0;
function snowVideo(){if(snowVid)return snowVid;const v=document.createElement('video');v.muted=true;v.loop=true;v.playsInline=true;v.setAttribute('playsinline','');v.setAttribute('aria-hidden','true');v.style.cssText='position:fixed;width:1px;height:1px;opacity:0;pointer-events:none;left:-9px;top:-9px';v.src=neveSrc();document.body.append(v);snowVid=v;return v}
function snowDraw(t){snowRAF=requestAnimationFrame(snowDraw);if(t-snowLast<33)return;snowLast=t;const v=snowVid;if(!v||v.readyState<2)return;
 const vw=v.videoWidth,vh=v.videoHeight;
 for(const cv of snowVis){const r=cv.getBoundingClientRect();if(!r.width)continue;const dpr=Math.min(2,window.devicePixelRatio||1),W=Math.round(r.width*dpr),H=Math.round(r.height*dpr);if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H}
  const s=Math.max(W/vw,H/vh),sw=W/s,sh=H/s,off=+cv.dataset.off||0,sy=((vh-sh)*off);const ctx=cv.getContext('2d');ctx.drawImage(v,(vw-sw)/2,sy,sw,sh,0,0,W,H)}}
function snowCards(){const arts=[...document.querySelectorAll('.combo-art,.hero-v14 .hero-left')];if(!arts.length)return;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){arts.forEach(a=>a.classList.add('snow-still'));return}
 const v=snowVideo();if(!snowIO)snowIO=new IntersectionObserver(es=>{for(const e of es){if(e.isIntersecting)snowVis.add(e.target);else snowVis.delete(e.target)}if(snowVis.size){v.play().catch(()=>{});if(!snowRAF)snowRAF=requestAnimationFrame(snowDraw)}else{v.pause();cancelAnimationFrame(snowRAF);snowRAF=0}},{rootMargin:'60px'});
 for(const [i,a] of arts.entries()){if(a.querySelector('canvas.snow-cv'))continue;a.classList.add('has-snow');const cv=document.createElement('canvas');cv.className='snow-cv';cv.setAttribute('aria-hidden','true');cv.dataset.off=((i*0.37)%1).toFixed(2);a.prepend(cv);snowIO.observe(cv)}
 for(const cv of [...snowVis])if(!cv.isConnected)snowVis.delete(cv)}
(function(){const _r=render;render=function(){_r.apply(this,arguments);try{snowCards()}catch{}}})();
document.addEventListener('visibilitychange',()=>{if(!snowVid)return;if(document.hidden)snowVid.pause();else if(snowVis.size)snowVid.play().catch(()=>{})});

