function adsStrip(where){const list=ADS17[where]||[];if(!list.length)return '';const i=adIdx[where]%list.length,a=list[i];
 return `<section class="ad-strip ${a.c?'ad-neon':''}" data-where="${where}" aria-label="Ofertas" style="${a.c?'--adc:'+a.c:''}">${a.img.startsWith('ad-ess')?'<span class="ad-chip">💨 Essências · toque para ver</span>':''}<button type="button" class="ad-slide" data-adgo="${i}" aria-label="${esc(a.alt)}"><span class="ad-blur" style="background-image:url('${ADS[a.img]}')"></span><img src="${ADS[a.img]}" alt="${esc(a.alt)}"></button>${list.length>1?`<button type="button" class="ad-nav prev" data-adnav="-1" aria-label="Anterior">‹</button><button type="button" class="ad-nav next" data-adnav="1" aria-label="Próximo">›</button><div class="ad-dots">${list.length>8?`<b class="ad-count">${i+1}/${list.length}</b>`:list.map((_,j)=>`<i class="${j===i?'on':''}"></i>`).join('')}</div>`:''}${where==='tab'||where==='ess'?'<p class="ad-legal">Venda proibida para menores de 18 anos · Fumar causa câncer · Disque Saúde 136</p>':''}</section>`}
function adShow(where,step){const s=document.querySelector(`.ad-strip[data-where="${where}"]`);if(!s)return;adIdx[where]=(adIdx[where]+step+ADS17[where].length)%ADS17[where].length;const tmp=document.createElement('div');tmp.innerHTML=adsStrip(where);s.replaceWith(tmp.firstElementChild)}
