/* ---------- v17.2 · grupo "Cervejas 600 ml": uma foto, depois escolhe a marca ---------- */
const GROUPS={'grp-600':{name:'Cervejas 600 ml',desc:'Skol, Brahma, Original, Amstel, Itaipava e Heineken · garrafa pra dividir',cat:'Garrafa',ids:['skol-600','brahma-600','original-600','amstel-600','itaipava-600','heineken-600']}};
let grpDraft=null;
function grpItems(g){return GROUPS[g].ids.map(item).filter(p=>p&&onlineOk(p))}
function grpCard(g){const G=GROUPS[g],its=grpItems(g);if(!its.length)return '';const min=Math.min(...its.map(p=>p.price10)),n=its.reduce((a,p)=>a+(cart['p:'+p.id]||0),0);
 return `<article class="product-card grp-card"><div class="product-photo">${productPhoto(g)}</div><div class="product-content"><span class="badge-cold">❄️ ESCOLHA K10</span><small>${esc(G.cat)}</small><h3>${esc(G.name)}</h3><p class="desc">${esc(G.desc)}</p><strong class="price"><small style="font-size:12px;font-weight:700">a partir de</small> ${money(min)}</strong>${button(n?`🍺 Escolher marcas (${n})`:'🍺 Escolher marcas','grp-open','button red',`data-id="${g}"`)}</div></article>`}
function drawGroup(){const {g,dist}=grpDraft,its=grpItems(g),tot=its.reduce((a,p)=>a+(dist[p.id]||0),0),val=its.reduce((a,p)=>a+(dist[p.id]||0)*p.price10,0);
 popup('🍺 '+GROUPS[g].name+' · escolha as marcas',`<p class="page-summary" style="margin-top:0">Escolha uma marca ou misture: use + e − em cada uma.</p><div class="flav-grid">${its.map(p=>`<div class="flav ${dist[p.id]?'on':''}"><img src="${img(p.id)}" alt="${esc(p.name)}"><b>${esc(p.name.replace(' 600 ml',''))}</b><span class="tiny" style="color:#6fd8ff;font-weight:800">${money(p.price10)}</span><div class="quantity"><button type="button" data-action="grp-step" data-value="${p.id}" data-delta="-1" aria-label="Menos ${esc(p.name)}">−</button><b>${dist[p.id]||0}</b><button type="button" data-action="grp-step" data-value="${p.id}" data-delta="1" aria-label="Mais ${esc(p.name)}">+</button></div></div>`).join('')}</div><div class="form-actions" style="margin:12px 0">${button('🎨 Misto: 1 de cada','grp-mix','button small dark')}${button('Limpar','grp-clear','button small outline')}</div><div class="summary total"><span>${tot} garrafa(s)</span><b>${money(val)}</b></div>${button(tot?'✓ Colocar no carrinho':'Remover do pedido','grp-ok','button block')}`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action^="grp-"]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const a=el.dataset.action;
 if(a==='grp-open'){const g=el.dataset.id,dist={};for(const p of grpItems(g))if(cart['p:'+p.id])dist[p.id]=cart['p:'+p.id];grpDraft={g,dist};drawGroup();return}
 if(!grpDraft)return;const d=grpDraft.dist;
 if(a==='grp-step'){d[el.dataset.value]=Math.max(0,Math.min(99,(d[el.dataset.value]||0)+Number(el.dataset.delta)));drawGroup()}
 else if(a==='grp-mix'){for(const p of grpItems(grpDraft.g))d[p.id]=(d[p.id]||0)+1;drawGroup()}
 else if(a==='grp-clear'){grpDraft.dist={};drawGroup()}
 else if(a==='grp-ok'){let tot=0;for(const p of grpItems(grpDraft.g)){const k='p:'+p.id,want=d[p.id]||0,has=cart[k]||0;if(want!==has)changeCart(k,want-has);tot+=want}grpDraft=null;closeModal();render();toast(tot?`🍺 ${tot} garrafa(s) de 600 ml no carrinho`:'Removido.')}},true);
