 z.innerHTML=`<div class="adz-top"><span>🔍 Toque na imagem para ampliar</span><button type="button" class="adz-x" aria-label="Fechar">✕</button></div><div class="adz-scroll"><img src="${ADS[a.img]}" alt="${esc(a.alt)}"></div><div class="adz-bot"><button type="button" class="button adz-go">🛒 Ver produto</button></div>`;
 document.body.append(z);document.body.style.overflow='hidden';const sc=z.querySelector('.adz-scroll'),im=z.querySelector('img');
 const close=()=>{z.remove();document.body.style.overflow=''};
 z.querySelector('.adz-x').onclick=close;z.querySelector('.adz-go').onclick=()=>{close();adGoTo(a)};
