let subcat='Todos',subLastCat=null;
function subText(id){if(id==='grp-600')return 'cervejas 600 ml garrafa';const p=item(id);return p?(p.name+' '+p.description+' '+id).toLowerCase():''}
(function(){const _c4=catalog;catalog=function(){let h=_c4.apply(this,arguments);if(subLastCat!==category){subcat='Todos';subLastCat=category}
 const rules=SUBS[category];if(!rules||search)return h;
 const doc=document.createElement('div');doc.innerHTML=h;const grid=doc.querySelector('.products');if(!grid)return h;
 const cards=[...grid.querySelectorAll('.product-card')].map(c=>{const b=c.querySelector('[data-id]');const id=b?b.dataset.id.replace(/^p:/,''):'';return {c,t:subText(id)}});
 const prim=rules.filter(r=>!r[2]),extra=rules.filter(r=>r[2]);
 const groups=rules.map(r=>({n:r[0],items:[]}));
 for(const x of cards){const pi=prim.findIndex(r=>r[1].test(x.t));const g=pi>=0?groups.find(g=>g.n===prim[pi][0]):groups[groups.length-1];if(pi>=0||!extra.length)g.items.push(x);for(const r of extra)if(r[1].test(x.t))groups.find(g=>g.n===r[0]).items.push({c:x.c.cloneNode(true),t:x.t,dup:true})}
 const live=groups.filter(g=>g.items.length);if(live.length<2)return h;
 const chips=`<div class="sub-pills">${['Todos',...live.map(g=>g.n)].map(n=>`<button type="button" data-sub="${esc(n)}" class="${subcat===n?'active':''}">${esc(n)}${n==='Todos'?'':` <small>${live.find(g=>g.n===n).items.length}</small>`}</button>`).join('')}</div>`;
 const wrap=document.createElement('div');
 const show=subcat==='Todos'?live.filter(g=>!rules.find(r=>r[0]===g.n)[2]):live.filter(g=>g.n===subcat);
 for(const g of show){const s=document.createElement('section');s.className='sub-sec';s.innerHTML=`<h2 class="sub-h">${esc(g.n)} <small>${g.items.length}</small></h2><div class="products"></div>`;const pg=s.querySelector('.products');for(const x of g.items)pg.append(x.dup?x.c:x.c);wrap.append(s)}
 grid.replaceWith(wrap);const t=document.createElement('div');t.innerHTML=chips;wrap.before(t.firstElementChild);return doc.innerHTML}})();
