const setSess=s=>{sess=s;LS.set(SKEY,s)};
const sessOf=j=>({access_token:j.access_token,refresh_token:j.refresh_token,expires_at:j.expires_at||Math.floor(Date.now()/1000)+(j.expires_in||3600),email:j.user&&j.user.email});
