/* v46 · clientes no banco online (tabela k10_clientes): o portal lê, aprova e cria senha nova */
const CLI_SEL='k10_clientes?select=id,codigo,telefone,doc,conta,dados,criado_em,atualizado_em',CK='k10-cli-known';
let cliOn=false,lastCli='',cliN=0;
function cliOf(r){const d=Object.assign({},r.dados||{});delete d.passHash;delete d._tok;d.id=r.id;d.code=r.codigo;d.phone=d.phone||r.telefone;d.doc=r.doc||d.doc||'';d.account=!!r.conta;
 if(!d.status)d.status='pendente';if(!d.created&&r.criado_em)d.created=new Date(r.criado_em).toLocaleString('pt-BR');return d}
const cliKey=c=>{const d=clone(c||{});delete d.passHash;delete d._sb;return canon(d)};
const onlyNum=s=>String(s||'').replace(/\D/g,'');
async function cliAll(){let out=[],off=0;for(;;){const r=await rest(CLI_SEL+'&order=codigo.asc&limit=1000&offset='+off);out=out.concat(r||[]);if(!r||r.length<1000)break;off+=1000}return out}
async function cliInit(est){try{const rows=await cliAll();SNAP.k={};const known=new Set(LS.get(CK,[])),map=new Map(),tels=new Set();
  for(const r of rows){const c=cliOf(r);map.set(c.id,c);tels.add(String(r.telefone));SNAP.k[c.id]=cliKey(c)}
  const cur=DB.customers||[],old=(est||[]).find(r=>r.chave==='customers');
  const local=cur.concat(old&&Array.isArray(old.dados)?old.dados.filter(x=>x&&!cur.some(y=>y.id===x.id)):[]);
  const keep=[];for(const c of local){if(!c||!c.id||map.has(c.id)||known.has(c.id))continue;const t=onlyNum(c.phone);if(t&&tels.has(t))continue;keep.push(c)}
  DB.customers=[...map.values(),...keep];lastCli=rows.reduce((a,r)=>r.atualizado_em>a?r.atualizado_em:a,'');LS.set(CK,[...map.keys()]);cliOn=true;
  if(old)rest('k10_estado?chave=eq.customers',{method:'DELETE'}).catch(()=>{});return true}
 catch(e){console.warn('clientes',e.message);cliOn=false;if(isAdmin())toast('Não consegui ler os clientes do banco: '+e.message,true);return false}}
async function cliPush(){if(!cliOn||!SNAP||!SNAP.k)return;try{
 for(const c of (DB.customers||[]).slice()){if(!c||!c.id)continue;const j=cliKey(c);if(SNAP.k[c.id]===j)continue;const d=clone(c);delete d.passHash;delete d._sb;delete d._tok;
  if(c.id in SNAP.k){await rest('k10_clientes?id=eq.'+encodeURIComponent(c.id),{method:'PATCH',body:{dados:d},prefer:'return=minimal'});SNAP.k[c.id]=j;continue}
  const tel=onlyNum(c.phone);if(tel.length<10||tel.length>13)continue;
  try{const r=await rest('k10_clientes?select=id,codigo',{method:'POST',body:{id:c.id,telefone:tel,doc:onlyNum(c.doc)||null,dados:d},prefer:'return=representation'});
   const row=r&&r[0];if(row&&row.codigo)c.code=row.codigo;c.account=false;SNAP.k[c.id]=cliKey(c);LS.set(CK,Object.keys(SNAP.k));_origSave()}
  catch(e){if(e.status===409){DB.customers=DB.customers.filter(x=>x!==c);cliN=9;_origSave();continue}throw e}}
 }catch(e){console.warn('clientes push',e.message)}}
async function cliPull(){if(!cliOn){if(++cliN%10===0)return await cliInit([]);return false}
 try{cliN++;const full=cliN%10===0||!lastCli;const rows=full?await cliAll():await rest(CLI_SEL+'&atualizado_em=gt.'+encodeURIComponent(lastCli)+'&order=atualizado_em.asc');
  let ch=false;const seen=new Set();
  for(const r of rows){seen.add(r.id);if(r.atualizado_em>lastCli)lastCli=r.atualizado_em;const c=cliOf(r),j=cliKey(c),loc=DB.customers.find(x=>x.id===c.id);
   if(loc&&(c.id in SNAP.k)&&cliKey(loc)!==SNAP.k[c.id])continue;
   if(!loc){DB.customers.push(c);ch=true}else if(cliKey(loc)!==j){for(const k of Object.keys(loc))delete loc[k];Object.assign(loc,c);ch=true}SNAP.k[c.id]=j}
  if(full)for(const id of Object.keys(SNAP.k))if(!seen.has(id)){const i=DB.customers.findIndex(x=>x.id===id);if(i>=0){DB.customers.splice(i,1);ch=true}delete SNAP.k[id]}
  if(ch||full)LS.set(CK,Object.keys(SNAP.k));return ch}
 catch(e){console.warn('clientes',e.message);return false}}
