const LOCKK='k10-staff-lock';
const lockLeft=()=>{const st=LS.get(LOCKK,{})||{};return st.until&&Date.now()<st.until?Math.ceil((st.until-Date.now())/60000):0};
const lockFail=()=>{const st=LS.get(LOCKK,{})||{};st.n=(st.n||0)+1;if(st.n>=5){LS.set(LOCKK,{until:Date.now()+15*60000,n:0});return true}LS.set(LOCKK,st);return false};
