staffSecurity=function(){return `<div class="page-title"><h2>🔐 Segurança da conta</h2><p>Sua conta fica no Supabase. Nenhuma senha é guardada neste aparelho.</p></div><div class="two-column"><section class="panel stack"><h3>Trocar minha senha</h3><form id="sbPassForm" class="stack"><label class="field">Senha atual<input type="password" name="old" required autocomplete="current-password"></label><label class="field">Nova senha (mín. 10 caracteres)<input type="password" name="pass" required minlength="10" autocomplete="new-password"></label><label class="field">Repita a nova senha<input type="password" name="pass2" required minlength="10" autocomplete="new-password"></label><button class="button small" type="submit">Trocar senha</button></form><p class="tiny muted">A sessão encerra sozinha após ${STAFF_IDLE_MIN} min sem uso e depois de 12 horas.</p></section><section class="panel stack"><h3>Verificação em duas etapas</h3>${notice('A verificação em duas etapas antiga funcionava só neste aparelho e por isso foi desligada. O próximo passo é ativar o MFA do próprio Supabase.')}</section></div>`};
