try{const sm=sessionStorage.getItem('k10-sair-msg');if(sm!==null){sessionStorage.removeItem('k10-sair-msg');if(sm)setTimeout(()=>toast(sm,true),700)}}catch(_){}
setTimeout(()=>{if(DB.activeUser&&!sess){forceLogout();return}if(sess&&!DB.activeUser){sairSupabase();return}if(sess&&DB.activeUser)startStaff()},200);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&SNAP)pull()});
